export const SETUP_SQL = "-- Amryn™ AIGrowthIntelligence® — complete database setup\n--\n-- Generated by scripts/build-setup-sql.mjs from supabase/migrations.\n-- Do not edit this file; edit the migrations and regenerate.\n--\n-- Paste the whole thing into the Supabase SQL editor and run it once.\n-- It is wrapped in a single transaction: if any statement fails, nothing is\n-- applied and the error names where it stopped. A half-applied schema is the\n-- one outcome this exists to prevent.\n--\n-- Safe on an empty database. NOT safe to run twice — the second run fails on\n-- the first `create table`, having changed nothing.\n\nbegin;\n\n-- ══════════════════════════════════════════════════════════════════════\n-- 20260829090000_01_foundation.sql\n-- ══════════════════════════════════════════════════════════════════════\ndo $setup$ begin raise notice 'applying 20260829090000_01_foundation.sql'; end $setup$;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- Amryn™ AIGrowthIntelligence® Software\n-- Migration 01 — Foundation: tenancy, identity, org structure, RBAC\n--\n-- Tenancy model\n-- -------------\n-- Every business table carries organisation_id and is protected by Row Level\n-- Security. A member's reach inside their organisation is further narrowed by\n-- a *scope*: org-wide, a set of regions, a set of branches, or a set of\n-- departments. Scope is resolved in SQL (not in the app) so that a bug in the\n-- application layer cannot widen what a user can read.\n-- ═══════════════════════════════════════════════════════════════════════════\n\ncreate extension if not exists \"pgcrypto\";\ncreate extension if not exists \"citext\";\n\ncreate schema if not exists amryn;\ncomment on schema amryn is 'Amryn internal helper functions. Not exposed through PostgREST.';\n\nrevoke all on schema amryn from public, anon, authenticated;\ngrant usage on schema amryn to authenticated, service_role;\n\n-- ── enums ─────────────────────────────────────────────────────────────────\n\ncreate type public.org_role as enum (\n  'super_admin',\n  'org_admin',\n  'executive',\n  'regional_manager',\n  'branch_manager',\n  'department_manager',\n  'analyst',\n  'viewer'\n);\n\ncreate type public.scope_kind as enum ('organisation', 'region', 'branch', 'department');\n\ncreate type public.member_status as enum ('invited', 'active', 'suspended');\n\ncreate type public.priority_level as enum ('critical', 'high', 'medium', 'low');\n\ncreate type public.trend_direction as enum ('up', 'down', 'flat');\n\ncreate type public.subscription_plan as enum ('starter', 'growth', 'professional', 'enterprise');\n\ncreate type public.subscription_status as enum ('trialing', 'active', 'past_due', 'cancelled');\n\n-- ── organisations ─────────────────────────────────────────────────────────\n\ncreate table public.organisations (\n  id                uuid primary key default gen_random_uuid(),\n  name              text not null check (length(btrim(name)) between 2 and 160),\n  slug              citext not null unique check (slug ~ '^[a-z0-9][a-z0-9-]{1,62}$'),\n  industry          text,\n  country_code      char(2) not null default 'ZA',\n  currency_code     char(3) not null default 'ZAR',\n  timezone          text not null default 'Africa/Johannesburg',\n  fiscal_year_start smallint not null default 1 check (fiscal_year_start between 1 and 12),\n  -- Strategy profile the OpportunityRadar® scores relevance against.\n  strategy_profile  jsonb not null default '{}'::jsonb,\n  settings          jsonb not null default '{}'::jsonb,\n  created_at        timestamptz not null default now(),\n  updated_at        timestamptz not null default now(),\n  deleted_at        timestamptz\n);\n\ncomment on column public.organisations.strategy_profile is\n  'Declared markets, segments, capabilities and growth intents. Feeds opportunity relevance and strategic-alignment scoring.';\n\n-- ── user profiles (mirrors auth.users) ────────────────────────────────────\n\ncreate table public.user_profiles (\n  id           uuid primary key references auth.users (id) on delete cascade,\n  email        citext not null,\n  full_name    text,\n  job_title    text,\n  avatar_url   text,\n  locale       text not null default 'en-ZA',\n  theme        text not null default 'system' check (theme in ('light', 'medium', 'dark', 'system')),\n  last_seen_at timestamptz,\n  created_at   timestamptz not null default now(),\n  updated_at   timestamptz not null default now()\n);\n\n-- ── organisational structure ──────────────────────────────────────────────\n\ncreate table public.regions (\n  id              uuid primary key default gen_random_uuid(),\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  name            text not null,\n  code            text,\n  created_at      timestamptz not null default now(),\n  updated_at      timestamptz not null default now(),\n  deleted_at      timestamptz,\n  unique (organisation_id, name)\n);\n\ncreate table public.branches (\n  id              uuid primary key default gen_random_uuid(),\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  region_id       uuid references public.regions (id) on delete set null,\n  name            text not null,\n  code            text,\n  city            text,\n  opened_on       date,\n  headcount       integer check (headcount >= 0),\n  created_at      timestamptz not null default now(),\n  updated_at      timestamptz not null default now(),\n  deleted_at      timestamptz,\n  unique (organisation_id, name)\n);\n\ncreate table public.departments (\n  id              uuid primary key default gen_random_uuid(),\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  branch_id       uuid references public.branches (id) on delete set null,\n  name            text not null,\n  function        text,\n  created_at      timestamptz not null default now(),\n  updated_at      timestamptz not null default now(),\n  deleted_at      timestamptz,\n  unique (organisation_id, branch_id, name)\n);\n\n-- A branch's region, and a department's branch, must belong to the same\n-- organisation as the row itself. Two small functions rather than one with a\n-- dispatch argument: PL/pgSQL resolves NEW's fields when the expression is\n-- planned, so a shared body would reference columns the other table lacks.\n\ncreate or replace function amryn.assert_branch_region_same_org()\nreturns trigger\nlanguage plpgsql\nas $$\ndeclare\n  parent_org uuid;\nbegin\n  if new.region_id is not null then\n    select organisation_id into parent_org from public.regions where id = new.region_id;\n    if parent_org is distinct from new.organisation_id then\n      raise exception 'region % belongs to a different organisation', new.region_id;\n    end if;\n  end if;\n  return new;\nend;\n$$;\n\ncreate or replace function amryn.assert_department_branch_same_org()\nreturns trigger\nlanguage plpgsql\nas $$\ndeclare\n  parent_org uuid;\nbegin\n  if new.branch_id is not null then\n    select organisation_id into parent_org from public.branches where id = new.branch_id;\n    if parent_org is distinct from new.organisation_id then\n      raise exception 'branch % belongs to a different organisation', new.branch_id;\n    end if;\n  end if;\n  return new;\nend;\n$$;\n\ncreate trigger branches_same_org\n  before insert or update on public.branches\n  for each row execute function amryn.assert_branch_region_same_org();\n\ncreate trigger departments_same_org\n  before insert or update on public.departments\n  for each row execute function amryn.assert_department_branch_same_org();\n\n-- ── membership ────────────────────────────────────────────────────────────\n\ncreate table public.organisation_members (\n  id              uuid primary key default gen_random_uuid(),\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  user_id         uuid not null references auth.users (id) on delete cascade,\n  role            public.org_role not null default 'viewer',\n  status          public.member_status not null default 'active',\n  scope_kind      public.scope_kind not null default 'organisation',\n  -- Ids of the regions / branches / departments this member may see. Empty for\n  -- scope_kind = 'organisation'.\n  scope_ids       uuid[] not null default '{}',\n  invited_by      uuid references auth.users (id) on delete set null,\n  invited_at      timestamptz,\n  joined_at       timestamptz not null default now(),\n  created_at      timestamptz not null default now(),\n  updated_at      timestamptz not null default now(),\n  unique (organisation_id, user_id),\n  constraint scope_ids_match_kind check (\n    (scope_kind = 'organisation' and cardinality(scope_ids) = 0)\n    or (scope_kind <> 'organisation' and cardinality(scope_ids) > 0)\n  )\n);\n\ncreate index organisation_members_user_idx on public.organisation_members (user_id) where status = 'active';\ncreate index organisation_members_org_idx on public.organisation_members (organisation_id);\n\n-- ── permissions ───────────────────────────────────────────────────────────\n\ncreate table public.permissions (\n  key         text primary key check (key ~ '^[a-z][a-z0-9_]*$'),\n  category    text not null,\n  description text not null\n);\n\ncreate table public.role_permissions (\n  role            public.org_role not null,\n  permission_key  text not null references public.permissions (key) on delete cascade,\n  primary key (role, permission_key)\n);\n\n-- Per-member grants and revocations layered on top of the role defaults.\ncreate table public.member_permission_overrides (\n  id              uuid primary key default gen_random_uuid(),\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  member_id       uuid not null references public.organisation_members (id) on delete cascade,\n  permission_key  text not null references public.permissions (key) on delete cascade,\n  granted         boolean not null,\n  created_at      timestamptz not null default now(),\n  unique (member_id, permission_key)\n);\n\n-- ── subscriptions and billing ─────────────────────────────────────────────\n\ncreate table public.subscriptions (\n  id                   uuid primary key default gen_random_uuid(),\n  organisation_id      uuid not null unique references public.organisations (id) on delete cascade,\n  plan                 public.subscription_plan not null default 'starter',\n  status               public.subscription_status not null default 'trialing',\n  seats                integer not null default 3 check (seats > 0),\n  data_source_limit    integer not null default 2 check (data_source_limit >= 0),\n  ai_credits_monthly   integer not null default 500 check (ai_credits_monthly >= 0),\n  ai_credits_used      integer not null default 0 check (ai_credits_used >= 0),\n  price_cents_monthly  integer not null default 99900,\n  currency_code        char(3) not null default 'ZAR',\n  trial_ends_at        timestamptz,\n  current_period_start timestamptz not null default date_trunc('month', now()),\n  current_period_end   timestamptz not null default (date_trunc('month', now()) + interval '1 month'),\n  created_at           timestamptz not null default now(),\n  updated_at           timestamptz not null default now()\n);\n\ncreate table public.billing_records (\n  id              uuid primary key default gen_random_uuid(),\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  description     text not null,\n  amount_cents    integer not null,\n  currency_code   char(3) not null default 'ZAR',\n  status          text not null default 'paid' check (status in ('draft', 'due', 'paid', 'failed', 'refunded')),\n  issued_on       date not null default current_date,\n  paid_at         timestamptz,\n  external_ref    text,\n  created_at      timestamptz not null default now()\n);\n\ncreate index billing_records_org_idx on public.billing_records (organisation_id, issued_on desc);\n\n-- ── audit log ─────────────────────────────────────────────────────────────\n\ncreate table public.audit_logs (\n  id              bigint generated always as identity primary key,\n  organisation_id uuid references public.organisations (id) on delete cascade,\n  actor_id        uuid references auth.users (id) on delete set null,\n  action          text not null,\n  entity_type     text not null,\n  entity_id       text,\n  summary         text,\n  metadata        jsonb not null default '{}'::jsonb,\n  ip_address      inet,\n  user_agent      text,\n  created_at      timestamptz not null default now()\n);\n\ncreate index audit_logs_org_idx on public.audit_logs (organisation_id, created_at desc);\ncreate index audit_logs_actor_idx on public.audit_logs (actor_id, created_at desc);\n\n-- PostgREST answers from a cached copy of the schema and is not told by\n-- applying SQL. Without this, everything above exists and stays invisible to\n-- the application — which reads exactly like a migration that never ran.\nnotify pgrst, 'reload schema';\n\n-- ══════════════════════════════════════════════════════════════════════\n-- 20260829090100_02_intelligence.sql\n-- ══════════════════════════════════════════════════════════════════════\ndo $setup$ begin raise notice 'applying 20260829090100_02_intelligence.sql'; end $setup$;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- Amryn™ AIGrowthIntelligence® Software\n-- Migration 02 — Intelligence domain\n--   · Data plane        : sources, connections, imports, normalised records\n--   · AI DigitalTwin®   : metrics, health scores, events, insights\n--   · AI OpportunityRadar® : market signals, competitors, opportunities\n--   · Decision layer    : recommendations, goals, risks, alerts, reports\n-- ═══════════════════════════════════════════════════════════════════════════\n\n-- ── enums ─────────────────────────────────────────────────────────────────\n\ncreate type public.data_source_category as enum (\n  'accounting', 'crm', 'pos', 'erp', 'spreadsheet', 'database', 'api', 'manual'\n);\n\ncreate type public.connection_status as enum ('pending', 'connected', 'syncing', 'error', 'disabled');\n\ncreate type public.import_status as enum ('uploaded', 'mapping', 'validating', 'ready', 'importing', 'complete', 'failed');\n\ncreate type public.metric_kind as enum ('financial', 'sales', 'operational', 'customer', 'employee', 'growth', 'custom');\n\ncreate type public.health_category as enum ('financial', 'operational', 'sales', 'growth', 'customer', 'strategic');\n\ncreate type public.event_kind as enum ('anomaly', 'trend', 'threshold', 'milestone', 'ingestion', 'manual');\n\ncreate type public.opportunity_kind as enum (\n  'market_expansion', 'partnership', 'supplier', 'distribution',\n  'customer_acquisition', 'product', 'competitive_gap', 'investment'\n);\n\ncreate type public.opportunity_stage as enum (\n  'discovered', 'analysing', 'qualified', 'assigned', 'in_progress', 'won', 'lost', 'archived'\n);\n\ncreate type public.signal_kind as enum (\n  'market', 'industry', 'competitor', 'company_news', 'demand', 'trend', 'risk'\n);\n\ncreate type public.risk_status as enum ('open', 'mitigating', 'monitoring', 'closed', 'accepted');\n\ncreate type public.alert_status as enum ('new', 'acknowledged', 'assigned', 'snoozed', 'dismissed', 'resolved');\n\ncreate type public.goal_status as enum ('draft', 'active', 'at_risk', 'achieved', 'missed', 'cancelled');\n\ncreate type public.recommendation_status as enum ('new', 'accepted', 'in_progress', 'done', 'dismissed');\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- DATA PLANE\n-- ═══════════════════════════════════════════════════════════════════════════\n\ncreate table public.data_sources (\n  id              uuid primary key default gen_random_uuid(),\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  name            text not null,\n  category        public.data_source_category not null,\n  provider        text,\n  description     text,\n  created_by      uuid references auth.users (id) on delete set null,\n  created_at      timestamptz not null default now(),\n  updated_at      timestamptz not null default now(),\n  deleted_at      timestamptz,\n  unique (organisation_id, name)\n);\n\ncreate table public.data_connections (\n  id                 uuid primary key default gen_random_uuid(),\n  organisation_id    uuid not null references public.organisations (id) on delete cascade,\n  data_source_id     uuid not null references public.data_sources (id) on delete cascade,\n  status             public.connection_status not null default 'pending',\n  -- Non-secret connection shape only. Credentials live in the secret manager\n  -- and are referenced by handle, never stored in the tenant database.\n  config             jsonb not null default '{}'::jsonb,\n  credential_ref     text,\n  sync_schedule      text not null default 'daily'\n                       check (sync_schedule in ('manual', 'hourly', 'daily', 'weekly')),\n  field_mapping      jsonb not null default '{}'::jsonb,\n  last_synced_at     timestamptz,\n  last_error         text,\n  consecutive_errors integer not null default 0,\n  created_at         timestamptz not null default now(),\n  updated_at         timestamptz not null default now()\n);\n\ncreate index data_connections_org_idx on public.data_connections (organisation_id, status);\n\ncreate table public.data_imports (\n  id              uuid primary key default gen_random_uuid(),\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  data_source_id  uuid references public.data_sources (id) on delete set null,\n  filename        text,\n  status          public.import_status not null default 'uploaded',\n  row_count       integer not null default 0,\n  rows_imported   integer not null default 0,\n  rows_rejected   integer not null default 0,\n  column_mapping  jsonb not null default '{}'::jsonb,\n  validation      jsonb not null default '{}'::jsonb,\n  error_message   text,\n  uploaded_by     uuid references auth.users (id) on delete set null,\n  created_at      timestamptz not null default now(),\n  completed_at    timestamptz\n);\n\ncreate index data_imports_org_idx on public.data_imports (organisation_id, created_at desc);\n\n-- Rolling data-quality assessment per source, shown on the Data Health page.\ncreate table public.data_health_checks (\n  id                 uuid primary key default gen_random_uuid(),\n  organisation_id    uuid not null references public.organisations (id) on delete cascade,\n  data_source_id     uuid not null references public.data_sources (id) on delete cascade,\n  completeness_score numeric(5,2) not null check (completeness_score between 0 and 100),\n  freshness_hours    numeric(10,2),\n  error_count        integer not null default 0,\n  missing_fields     text[] not null default '{}',\n  checked_at         timestamptz not null default now()\n);\n\ncreate index data_health_checks_lookup_idx\n  on public.data_health_checks (organisation_id, data_source_id, checked_at desc);\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- AI DIGITALTWIN® — normalised business state\n-- ═══════════════════════════════════════════════════════════════════════════\n\n-- The metric *definition*: what is measured and how it should be read.\ncreate table public.business_metrics (\n  id                uuid primary key default gen_random_uuid(),\n  organisation_id   uuid not null references public.organisations (id) on delete cascade,\n  key               text not null check (key ~ '^[a-z][a-z0-9_]*$'),\n  label             text not null,\n  kind              public.metric_kind not null,\n  unit              text not null default 'currency'\n                      check (unit in ('currency', 'percent', 'count', 'days', 'ratio', 'score')),\n  -- Which direction is good. Used by trend and anomaly detection to decide\n  -- whether a move is an improvement or a deterioration.\n  higher_is_better  boolean not null default true,\n  target_value      numeric(18,4),\n  health_category   public.health_category,\n  health_weight     numeric(5,4) not null default 0 check (health_weight between 0 and 1),\n  is_active         boolean not null default true,\n  created_at        timestamptz not null default now(),\n  updated_at        timestamptz not null default now(),\n  unique (organisation_id, key)\n);\n\n-- The measurements. One row per metric per period per scope slice.\ncreate table public.metric_values (\n  id              uuid primary key default gen_random_uuid(),\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  metric_id       uuid not null references public.business_metrics (id) on delete cascade,\n  branch_id       uuid references public.branches (id) on delete cascade,\n  department_id   uuid references public.departments (id) on delete cascade,\n  period_start    date not null,\n  period_end      date not null,\n  granularity     text not null default 'month'\n                    check (granularity in ('day', 'week', 'month', 'quarter', 'year')),\n  value           numeric(18,4) not null,\n  data_source_id  uuid references public.data_sources (id) on delete set null,\n  created_at      timestamptz not null default now(),\n  constraint metric_period_ordered check (period_end >= period_start),\n  unique (metric_id, branch_id, department_id, period_start, granularity)\n);\n\ncreate index metric_values_series_idx\n  on public.metric_values (organisation_id, metric_id, period_start desc);\ncreate index metric_values_branch_idx\n  on public.metric_values (organisation_id, branch_id, period_start desc)\n  where branch_id is not null;\n\n-- Transactional detail behind the metrics, kept so the assistant can answer\n-- \"why\" rather than only \"what\".\ncreate table public.financial_records (\n  id              uuid primary key default gen_random_uuid(),\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  branch_id       uuid references public.branches (id) on delete set null,\n  department_id   uuid references public.departments (id) on delete set null,\n  occurred_on     date not null,\n  category        text not null,\n  subcategory     text,\n  amount_cents    bigint not null,\n  currency_code   char(3) not null default 'ZAR',\n  direction       text not null check (direction in ('income', 'expense')),\n  reference       text,\n  data_source_id  uuid references public.data_sources (id) on delete set null,\n  created_at      timestamptz not null default now()\n);\n\ncreate index financial_records_org_idx\n  on public.financial_records (organisation_id, occurred_on desc);\n\ncreate table public.sales_records (\n  id              uuid primary key default gen_random_uuid(),\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  branch_id       uuid references public.branches (id) on delete set null,\n  department_id   uuid references public.departments (id) on delete set null,\n  occurred_on     date not null,\n  customer_ref    text,\n  customer_name   text,\n  product_line    text,\n  quantity        numeric(14,3) not null default 1,\n  amount_cents    bigint not null,\n  currency_code   char(3) not null default 'ZAR',\n  margin_cents    bigint,\n  data_source_id  uuid references public.data_sources (id) on delete set null,\n  created_at      timestamptz not null default now()\n);\n\ncreate index sales_records_org_idx on public.sales_records (organisation_id, occurred_on desc);\ncreate index sales_records_customer_idx\n  on public.sales_records (organisation_id, customer_ref, occurred_on desc)\n  where customer_ref is not null;\n\ncreate table public.operational_records (\n  id              uuid primary key default gen_random_uuid(),\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  branch_id       uuid references public.branches (id) on delete set null,\n  department_id   uuid references public.departments (id) on delete set null,\n  occurred_on     date not null,\n  measure         text not null,\n  value           numeric(18,4) not null,\n  unit            text,\n  data_source_id  uuid references public.data_sources (id) on delete set null,\n  created_at      timestamptz not null default now()\n);\n\ncreate index operational_records_org_idx\n  on public.operational_records (organisation_id, measure, occurred_on desc);\n\n-- Health score history — the Digital Twin's headline reading over time.\ncreate table public.business_health_scores (\n  id                uuid primary key default gen_random_uuid(),\n  organisation_id   uuid not null references public.organisations (id) on delete cascade,\n  branch_id         uuid references public.branches (id) on delete cascade,\n  score             numeric(5,2) not null check (score between 0 and 100),\n  classification    text not null\n                      check (classification in ('excellent', 'healthy', 'attention', 'at_risk', 'critical')),\n  -- { financial: 78.4, operational: 62.0, ... } plus the weights in force.\n  category_scores   jsonb not null default '{}'::jsonb,\n  weights           jsonb not null default '{}'::jsonb,\n  contributing_metrics jsonb not null default '[]'::jsonb,\n  calculated_for    date not null,\n  calculated_at     timestamptz not null default now(),\n  unique (organisation_id, branch_id, calculated_for)\n);\n\ncreate index business_health_scores_idx\n  on public.business_health_scores (organisation_id, calculated_for desc);\n\n-- Configurable weighting per organisation (spec §26).\ncreate table public.health_score_weights (\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  category        public.health_category not null,\n  weight          numeric(5,4) not null check (weight between 0 and 1),\n  updated_at      timestamptz not null default now(),\n  primary key (organisation_id, category)\n);\n\n-- Things that happened inside the business.\ncreate table public.business_events (\n  id              uuid primary key default gen_random_uuid(),\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  branch_id       uuid references public.branches (id) on delete cascade,\n  department_id   uuid references public.departments (id) on delete cascade,\n  metric_id       uuid references public.business_metrics (id) on delete set null,\n  kind            public.event_kind not null,\n  severity        public.priority_level not null default 'low',\n  title           text not null,\n  detail          text,\n  evidence        jsonb not null default '{}'::jsonb,\n  occurred_at     timestamptz not null default now(),\n  created_at      timestamptz not null default now()\n);\n\ncreate index business_events_feed_idx\n  on public.business_events (organisation_id, occurred_at desc);\n\n-- What the Digital Twin concluded, as opposed to what merely happened.\ncreate table public.business_insights (\n  id               uuid primary key default gen_random_uuid(),\n  organisation_id  uuid not null references public.organisations (id) on delete cascade,\n  branch_id        uuid references public.branches (id) on delete cascade,\n  headline         text not null,\n  narrative        text not null,\n  category         public.health_category,\n  direction        public.trend_direction not null default 'flat',\n  impact_cents     bigint,\n  confidence       numeric(4,3) not null default 0.5 check (confidence between 0 and 1),\n  evidence         jsonb not null default '[]'::jsonb,\n  source_event_ids uuid[] not null default '{}',\n  generated_by     text not null default 'engine' check (generated_by in ('engine', 'llm', 'human')),\n  valid_from       date not null default current_date,\n  valid_to         date,\n  created_at       timestamptz not null default now()\n);\n\ncreate index business_insights_org_idx\n  on public.business_insights (organisation_id, created_at desc);\n\n-- PostgREST answers from a cached copy of the schema and is not told by\n-- applying SQL. Without this, everything above exists and stays invisible to\n-- the application — which reads exactly like a migration that never ran.\nnotify pgrst, 'reload schema';\n\n-- ══════════════════════════════════════════════════════════════════════\n-- 20260829090200_03_market_and_decisions.sql\n-- ══════════════════════════════════════════════════════════════════════\ndo $setup$ begin raise notice 'applying 20260829090200_03_market_and_decisions.sql'; end $setup$;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- Amryn™ AIGrowthIntelligence® Software\n-- Migration 03 — AI OpportunityRadar®, decision layer and assistant\n--\n-- Scanning policy: Amryn is a private-sector intelligence platform. Market\n-- sources carry a `sector_policy` and signals a `sector` so that public-sector\n-- tenders, programmes and events can be excluded by default (spec §2). The\n-- default org setting excludes them; an organisation may opt in explicitly.\n-- ═══════════════════════════════════════════════════════════════════════════\n\ncreate type public.market_sector as enum ('private', 'public', 'mixed', 'unknown');\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- EXTERNAL INTELLIGENCE\n-- ═══════════════════════════════════════════════════════════════════════════\n\ncreate table public.market_sources (\n  id              uuid primary key default gen_random_uuid(),\n  organisation_id uuid references public.organisations (id) on delete cascade,\n  name            text not null,\n  kind            text not null\n                    check (kind in ('news', 'industry_report', 'company_filing', 'jobs_board',\n                                    'directory', 'social', 'search_trend', 'manual')),\n  url             text,\n  -- Which sectors this source is allowed to contribute. Defaults to private\n  -- only, which is the platform's standing scanning posture.\n  sector_policy   public.market_sector[] not null default '{private}',\n  is_global       boolean not null default false,\n  reliability     numeric(4,3) not null default 0.7 check (reliability between 0 and 1),\n  last_scanned_at timestamptz,\n  is_active       boolean not null default true,\n  created_at      timestamptz not null default now(),\n  constraint global_sources_have_no_org check (\n    (is_global and organisation_id is null) or (not is_global and organisation_id is not null)\n  )\n);\n\ncreate table public.competitors (\n  id              uuid primary key default gen_random_uuid(),\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  name            text not null,\n  website         text,\n  description     text,\n  markets         text[] not null default '{}',\n  threat_level    public.priority_level not null default 'medium',\n  is_tracked      boolean not null default true,\n  created_at      timestamptz not null default now(),\n  updated_at      timestamptz not null default now(),\n  unique (organisation_id, name)\n);\n\ncreate table public.competitor_events (\n  id              uuid primary key default gen_random_uuid(),\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  competitor_id   uuid not null references public.competitors (id) on delete cascade,\n  kind            text not null\n                    check (kind in ('launch', 'expansion', 'pricing', 'partnership',\n                                    'hiring', 'funding', 'exit', 'other')),\n  title           text not null,\n  detail          text,\n  impact          public.priority_level not null default 'medium',\n  source_url      text,\n  observed_on     date not null default current_date,\n  created_at      timestamptz not null default now()\n);\n\ncreate index competitor_events_org_idx\n  on public.competitor_events (organisation_id, observed_on desc);\n\ncreate table public.market_signals (\n  id              uuid primary key default gen_random_uuid(),\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  market_source_id uuid references public.market_sources (id) on delete set null,\n  kind            public.signal_kind not null,\n  sector          public.market_sector not null default 'private',\n  title           text not null,\n  summary         text not null,\n  detail          text,\n  entities        text[] not null default '{}',\n  keywords        text[] not null default '{}',\n  relevance       numeric(4,3) not null default 0.5 check (relevance between 0 and 1),\n  confidence      numeric(4,3) not null default 0.5 check (confidence between 0 and 1),\n  source_url      text,\n  observed_at     timestamptz not null default now(),\n  created_at      timestamptz not null default now()\n);\n\ncreate index market_signals_feed_idx\n  on public.market_signals (organisation_id, observed_at desc);\ncreate index market_signals_sector_idx on public.market_signals (organisation_id, sector);\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- OPPORTUNITIES\n-- ═══════════════════════════════════════════════════════════════════════════\n\ncreate table public.opportunities (\n  id                  uuid primary key default gen_random_uuid(),\n  organisation_id     uuid not null references public.organisations (id) on delete cascade,\n  branch_id           uuid references public.branches (id) on delete set null,\n  title               text not null,\n  kind                public.opportunity_kind not null,\n  sector              public.market_sector not null default 'private',\n  counterparty        text,\n  summary             text not null,\n  why_it_matters      text,\n  recommended_action  text,\n  estimated_value_cents bigint,\n  currency_code       char(3) not null default 'ZAR',\n  stage               public.opportunity_stage not null default 'discovered',\n  score               numeric(5,2) check (score between 0 and 100),\n  classification      text check (classification in ('high_priority', 'strong', 'potential', 'monitor')),\n  closes_on           date,\n  source_signal_ids   uuid[] not null default '{}',\n  source_urls         text[] not null default '{}',\n  is_saved            boolean not null default false,\n  created_at          timestamptz not null default now(),\n  updated_at          timestamptz not null default now(),\n  deleted_at          timestamptz\n);\n\ncreate index opportunities_pipeline_idx\n  on public.opportunities (organisation_id, stage, score desc nulls last);\ncreate index opportunities_saved_idx\n  on public.opportunities (organisation_id) where is_saved;\n\n-- Every scoring run is kept, so a change in ranking is explainable.\ncreate table public.opportunity_scores (\n  id                  uuid primary key default gen_random_uuid(),\n  organisation_id     uuid not null references public.organisations (id) on delete cascade,\n  opportunity_id      uuid not null references public.opportunities (id) on delete cascade,\n  relevance           numeric(5,2) not null check (relevance between 0 and 100),\n  potential_value     numeric(5,2) not null check (potential_value between 0 and 100),\n  strategic_alignment numeric(5,2) not null check (strategic_alignment between 0 and 100),\n  urgency             numeric(5,2) not null check (urgency between 0 and 100),\n  confidence          numeric(5,2) not null check (confidence between 0 and 100),\n  competition         numeric(5,2) not null check (competition between 0 and 100),\n  total               numeric(5,2) not null check (total between 0 and 100),\n  weights             jsonb not null default '{}'::jsonb,\n  rationale           text,\n  scored_at           timestamptz not null default now()\n);\n\ncreate index opportunity_scores_idx\n  on public.opportunity_scores (opportunity_id, scored_at desc);\n\n-- Configurable scoring weights per organisation (spec §27).\ncreate table public.opportunity_score_weights (\n  organisation_id uuid primary key references public.organisations (id) on delete cascade,\n  weights         jsonb not null default\n    '{\"relevance\":0.25,\"potential_value\":0.20,\"strategic_alignment\":0.20,\"urgency\":0.15,\"confidence\":0.10,\"competition\":0.10}'::jsonb,\n  updated_at      timestamptz not null default now()\n);\n\ncreate table public.opportunity_assignments (\n  id              uuid primary key default gen_random_uuid(),\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  opportunity_id  uuid not null references public.opportunities (id) on delete cascade,\n  assignee_id     uuid not null references auth.users (id) on delete cascade,\n  assigned_by     uuid references auth.users (id) on delete set null,\n  due_on          date,\n  note            text,\n  released_at     timestamptz,\n  created_at      timestamptz not null default now()\n);\n\ncreate index opportunity_assignments_idx\n  on public.opportunity_assignments (organisation_id, assignee_id)\n  where released_at is null;\n\ncreate table public.opportunity_activities (\n  id              uuid primary key default gen_random_uuid(),\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  opportunity_id  uuid not null references public.opportunities (id) on delete cascade,\n  actor_id        uuid references auth.users (id) on delete set null,\n  kind            text not null\n                    check (kind in ('note', 'stage_change', 'assignment', 'score_change',\n                                    'ai_analysis', 'attachment')),\n  body            text,\n  metadata        jsonb not null default '{}'::jsonb,\n  created_at      timestamptz not null default now()\n);\n\ncreate index opportunity_activities_idx\n  on public.opportunity_activities (opportunity_id, created_at desc);\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- STRATEGY\n-- ═══════════════════════════════════════════════════════════════════════════\n\ncreate table public.goals (\n  id              uuid primary key default gen_random_uuid(),\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  branch_id       uuid references public.branches (id) on delete set null,\n  department_id   uuid references public.departments (id) on delete set null,\n  metric_id       uuid references public.business_metrics (id) on delete set null,\n  title           text not null,\n  description     text,\n  owner_id        uuid references auth.users (id) on delete set null,\n  baseline_value  numeric(18,4),\n  target_value    numeric(18,4) not null,\n  current_value   numeric(18,4),\n  unit            text not null default 'currency',\n  status          public.goal_status not null default 'active',\n  starts_on       date not null default current_date,\n  due_on          date not null,\n  created_at      timestamptz not null default now(),\n  updated_at      timestamptz not null default now()\n);\n\ncreate index goals_org_idx on public.goals (organisation_id, status, due_on);\n\ncreate table public.goal_progress (\n  id            uuid primary key default gen_random_uuid(),\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  goal_id       uuid not null references public.goals (id) on delete cascade,\n  value         numeric(18,4) not null,\n  note          text,\n  recorded_on   date not null default current_date,\n  recorded_by   uuid references auth.users (id) on delete set null,\n  created_at    timestamptz not null default now(),\n  unique (goal_id, recorded_on)\n);\n\ncreate table public.strategic_initiatives (\n  id              uuid primary key default gen_random_uuid(),\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  title           text not null,\n  thesis          text,\n  owner_id        uuid references auth.users (id) on delete set null,\n  status          text not null default 'proposed'\n                    check (status in ('proposed', 'approved', 'active', 'paused', 'complete', 'cancelled')),\n  goal_ids        uuid[] not null default '{}',\n  opportunity_ids uuid[] not null default '{}',\n  starts_on       date,\n  ends_on         date,\n  created_at      timestamptz not null default now(),\n  updated_at      timestamptz not null default now()\n);\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- RECOMMENDATIONS — where inside meets outside\n-- ═══════════════════════════════════════════════════════════════════════════\n\ncreate table public.ai_recommendations (\n  id                uuid primary key default gen_random_uuid(),\n  organisation_id   uuid not null references public.organisations (id) on delete cascade,\n  branch_id         uuid references public.branches (id) on delete set null,\n  title             text not null,\n  summary           text not null,\n  why_it_matters    text not null,\n  recommended_action text not null,\n  evidence          jsonb not null default '[]'::jsonb,\n  impact_cents      bigint,\n  impact_note       text,\n  confidence        numeric(4,3) not null default 0.5 check (confidence between 0 and 1),\n  priority          public.priority_level not null default 'medium',\n  status            public.recommendation_status not null default 'new',\n  -- Provenance: which internal insight and which external signal produced this.\n  insight_ids       uuid[] not null default '{}',\n  signal_ids        uuid[] not null default '{}',\n  opportunity_id    uuid references public.opportunities (id) on delete set null,\n  generated_by      text not null default 'engine' check (generated_by in ('engine', 'llm', 'human')),\n  owner_id          uuid references auth.users (id) on delete set null,\n  created_at        timestamptz not null default now(),\n  updated_at        timestamptz not null default now(),\n  expires_on        date\n);\n\ncreate index ai_recommendations_board_idx\n  on public.ai_recommendations (organisation_id, status, priority, created_at desc);\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- RISK AND ALERTS\n-- ═══════════════════════════════════════════════════════════════════════════\n\ncreate table public.risks (\n  id              uuid primary key default gen_random_uuid(),\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  branch_id       uuid references public.branches (id) on delete set null,\n  title           text not null,\n  description     text,\n  category        text not null default 'operational'\n                    check (category in ('financial', 'operational', 'market', 'customer',\n                                        'compliance', 'people', 'technology', 'supply')),\n  likelihood      smallint not null default 3 check (likelihood between 1 and 5),\n  impact          smallint not null default 3 check (impact between 1 and 5),\n  -- Stored, not generated, so historical scores survive a scale change.\n  severity        public.priority_level not null default 'medium',\n  status          public.risk_status not null default 'open',\n  owner_id        uuid references auth.users (id) on delete set null,\n  mitigation      text,\n  review_on       date,\n  created_at      timestamptz not null default now(),\n  updated_at      timestamptz not null default now()\n);\n\ncreate index risks_register_idx on public.risks (organisation_id, status, severity);\n\ncreate table public.risk_events (\n  id           uuid primary key default gen_random_uuid(),\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  risk_id      uuid not null references public.risks (id) on delete cascade,\n  actor_id     uuid references auth.users (id) on delete set null,\n  kind         text not null\n                 check (kind in ('raised', 'reassessed', 'mitigation', 'status_change', 'note', 'closed')),\n  body         text,\n  metadata     jsonb not null default '{}'::jsonb,\n  created_at   timestamptz not null default now()\n);\n\ncreate table public.alerts (\n  id              uuid primary key default gen_random_uuid(),\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  branch_id       uuid references public.branches (id) on delete set null,\n  department_id   uuid references public.departments (id) on delete set null,\n  severity        public.priority_level not null default 'medium',\n  status          public.alert_status not null default 'new',\n  title           text not null,\n  detail          text,\n  -- What raised it, so the alert can be traced back to its evidence.\n  source_kind     text not null default 'engine'\n                    check (source_kind in ('engine', 'threshold', 'sync', 'radar', 'manual')),\n  business_event_id uuid references public.business_events (id) on delete set null,\n  risk_id         uuid references public.risks (id) on delete set null,\n  opportunity_id  uuid references public.opportunities (id) on delete set null,\n  assignee_id     uuid references auth.users (id) on delete set null,\n  snoozed_until   timestamptz,\n  acknowledged_at timestamptz,\n  resolved_at     timestamptz,\n  created_at      timestamptz not null default now()\n);\n\ncreate index alerts_inbox_idx\n  on public.alerts (organisation_id, status, severity, created_at desc);\n\ncreate table public.notifications (\n  id           uuid primary key default gen_random_uuid(),\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  user_id      uuid not null references auth.users (id) on delete cascade,\n  title        text not null,\n  body         text,\n  href         text,\n  kind         text not null default 'info'\n                 check (kind in ('info', 'alert', 'opportunity', 'recommendation', 'system')),\n  read_at      timestamptz,\n  created_at   timestamptz not null default now()\n);\n\ncreate index notifications_user_idx\n  on public.notifications (user_id, created_at desc) where read_at is null;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- REPORTS AND ASSISTANT\n-- ═══════════════════════════════════════════════════════════════════════════\n\ncreate table public.reports (\n  id              uuid primary key default gen_random_uuid(),\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  kind            text not null\n                    check (kind in ('executive_summary', 'business_performance', 'financial',\n                                    'opportunity', 'market_intelligence', 'risk', 'ai_briefing')),\n  title           text not null,\n  parameters      jsonb not null default '{}'::jsonb,\n  content         jsonb not null default '{}'::jsonb,\n  period_start    date,\n  period_end      date,\n  generated_by    uuid references auth.users (id) on delete set null,\n  created_at      timestamptz not null default now()\n);\n\ncreate index reports_org_idx on public.reports (organisation_id, created_at desc);\n\ncreate table public.ai_conversations (\n  id              uuid primary key default gen_random_uuid(),\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  user_id         uuid not null references auth.users (id) on delete cascade,\n  title           text not null default 'New conversation',\n  created_at      timestamptz not null default now(),\n  updated_at      timestamptz not null default now()\n);\n\ncreate index ai_conversations_user_idx\n  on public.ai_conversations (user_id, updated_at desc);\n\ncreate table public.ai_messages (\n  id              uuid primary key default gen_random_uuid(),\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  conversation_id uuid not null references public.ai_conversations (id) on delete cascade,\n  role            text not null check (role in ('user', 'assistant', 'system', 'tool')),\n  content         text not null,\n  -- Data the answer was drawn from, so every claim is traceable.\n  citations       jsonb not null default '[]'::jsonb,\n  visualisations  jsonb not null default '[]'::jsonb,\n  suggested_actions jsonb not null default '[]'::jsonb,\n  tokens_used     integer,\n  model           text,\n  created_at      timestamptz not null default now()\n);\n\ncreate index ai_messages_thread_idx\n  on public.ai_messages (conversation_id, created_at);\n\n-- PostgREST answers from a cached copy of the schema and is not told by\n-- applying SQL. Without this, everything above exists and stays invisible to\n-- the application — which reads exactly like a migration that never ran.\nnotify pgrst, 'reload schema';\n\n-- ══════════════════════════════════════════════════════════════════════\n-- 20260829090300_04_security_rls.sql\n-- ══════════════════════════════════════════════════════════════════════\ndo $setup$ begin raise notice 'applying 20260829090300_04_security_rls.sql'; end $setup$;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- Amryn™ AIGrowthIntelligence® Software\n-- Migration 04 — Row Level Security\n--\n-- The rule this file enforces: a user reads a row only if\n--   (a) they are an ACTIVE member of that row's organisation, and\n--   (b) the row's branch/department falls inside their scope, and\n--   (c) for sensitive tables, they hold the relevant permission.\n--\n-- All three are decided in SQL. The application layer re-checks permissions to\n-- give good error messages, but it is not what keeps tenants apart.\n--\n-- The helper functions are SECURITY DEFINER on purpose: they read\n-- organisation_members, which is itself RLS-protected, and a policy that\n-- queried it directly would recurse.\n-- ═══════════════════════════════════════════════════════════════════════════\n\n-- ── helpers ───────────────────────────────────────────────────────────────\n\ncreate or replace function amryn.active_member(p_org uuid)\nreturns public.organisation_members\nlanguage sql\nstable\nsecurity definer\nset search_path = public, pg_temp\nas $$\n  select m.*\n  from public.organisation_members m\n  where m.organisation_id = p_org\n    and m.user_id = auth.uid()\n    and m.status = 'active'\n  limit 1;\n$$;\n\ncreate or replace function amryn.is_member(p_org uuid)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = public, pg_temp\nas $$\n  select exists (\n    select 1\n    from public.organisation_members m\n    where m.organisation_id = p_org\n      and m.user_id = auth.uid()\n      and m.status = 'active'\n  );\n$$;\n\ncreate or replace function amryn.member_role(p_org uuid)\nreturns public.org_role\nlanguage sql\nstable\nsecurity definer\nset search_path = public, pg_temp\nas $$\n  select m.role\n  from public.organisation_members m\n  where m.organisation_id = p_org\n    and m.user_id = auth.uid()\n    and m.status = 'active'\n  limit 1;\n$$;\n\n-- Administrative reach: may manage members, structure and connections.\ncreate or replace function amryn.is_org_admin(p_org uuid)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = public, pg_temp\nas $$\n  select coalesce(amryn.member_role(p_org) in ('super_admin', 'org_admin'), false);\n$$;\n\n-- Effective permission = role default, then any per-member override.\ncreate or replace function amryn.has_permission(p_org uuid, p_permission text)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = public, pg_temp\nas $$\n  with member as (\n    select m.id, m.role\n    from public.organisation_members m\n    where m.organisation_id = p_org\n      and m.user_id = auth.uid()\n      and m.status = 'active'\n    limit 1\n  ),\n  override as (\n    select o.granted\n    from public.member_permission_overrides o\n    join member on member.id = o.member_id\n    where o.permission_key = p_permission\n    limit 1\n  ),\n  role_default as (\n    select true as granted\n    from public.role_permissions rp\n    join member on member.role = rp.role\n    where rp.permission_key = p_permission\n    limit 1\n  )\n  select coalesce(\n    (select granted from override),\n    (select granted from role_default),\n    false\n  );\n$$;\n\n-- The branches a member may see. NULL means \"the whole organisation\".\ncreate or replace function amryn.visible_branch_ids(p_org uuid)\nreturns uuid[]\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  m public.organisation_members;\n  result uuid[];\nbegin\n  select * into m from amryn.active_member(p_org);\n  if m.id is null then\n    return '{}'::uuid[];\n  end if;\n\n  case m.scope_kind\n    when 'organisation' then\n      return null;                                   -- unrestricted\n    when 'region' then\n      select coalesce(array_agg(b.id), '{}')\n        into result\n        from public.branches b\n       where b.organisation_id = p_org\n         and b.region_id = any (m.scope_ids);\n    when 'branch' then\n      select coalesce(array_agg(b.id), '{}')\n        into result\n        from public.branches b\n       where b.organisation_id = p_org\n         and b.id = any (m.scope_ids);\n    when 'department' then\n      select coalesce(array_agg(distinct d.branch_id), '{}')\n        into result\n        from public.departments d\n       where d.organisation_id = p_org\n         and d.id = any (m.scope_ids)\n         and d.branch_id is not null;\n  end case;\n\n  return coalesce(result, '{}'::uuid[]);\nend;\n$$;\n\n-- Can this member see a row carrying p_branch?\n--   · a NULL branch is an organisation-level row, reserved for org-wide scope\n--   · otherwise the branch must fall inside the member's visible set\ncreate or replace function amryn.can_see_branch(p_org uuid, p_branch uuid)\nreturns boolean\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  visible uuid[];\nbegin\n  if not amryn.is_member(p_org) then\n    return false;\n  end if;\n\n  visible := amryn.visible_branch_ids(p_org);\n\n  if visible is null then\n    return true;                                     -- organisation-wide scope\n  end if;\n\n  if p_branch is null then\n    return false;                                    -- aggregate row, scoped member\n  end if;\n\n  return p_branch = any (visible);\nend;\n$$;\n\ncreate or replace function amryn.can_see_department(p_org uuid, p_department uuid)\nreturns boolean\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  m public.organisation_members;\n  parent_branch uuid;\nbegin\n  select * into m from amryn.active_member(p_org);\n  if m.id is null then\n    return false;\n  end if;\n\n  if p_department is null then\n    return m.scope_kind <> 'department';\n  end if;\n\n  if m.scope_kind = 'department' then\n    return p_department = any (m.scope_ids);\n  end if;\n\n  select branch_id into parent_branch\n    from public.departments\n   where id = p_department and organisation_id = p_org;\n\n  return amryn.can_see_branch(p_org, parent_branch);\nend;\n$$;\n\ngrant execute on function\n  amryn.is_member(uuid),\n  amryn.member_role(uuid),\n  amryn.is_org_admin(uuid),\n  amryn.has_permission(uuid, text),\n  amryn.visible_branch_ids(uuid),\n  amryn.can_see_branch(uuid, uuid),\n  amryn.can_see_department(uuid, uuid)\nto authenticated;\n\n-- active_member returns a whole member row; keep it internal.\nrevoke all on function amryn.active_member(uuid) from public, anon, authenticated;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- Enable RLS everywhere, then deny by default.\n-- ═══════════════════════════════════════════════════════════════════════════\n\ndo $$\ndeclare\n  t text;\nbegin\n  foreach t in array array[\n    'organisations','user_profiles','regions','branches','departments',\n    'organisation_members','permissions','role_permissions',\n    'member_permission_overrides','subscriptions','billing_records','audit_logs',\n    'data_sources','data_connections','data_imports','data_health_checks',\n    'business_metrics','metric_values','financial_records','sales_records',\n    'operational_records','business_health_scores','health_score_weights',\n    'business_events','business_insights',\n    'market_sources','competitors','competitor_events','market_signals',\n    'opportunities','opportunity_scores','opportunity_score_weights',\n    'opportunity_assignments','opportunity_activities',\n    'goals','goal_progress','strategic_initiatives','ai_recommendations',\n    'risks','risk_events','alerts','notifications','reports',\n    'ai_conversations','ai_messages'\n  ]\n  loop\n    execute format('alter table public.%I enable row level security', t);\n    execute format('alter table public.%I force row level security', t);\n  end loop;\nend;\n$$;\n\n-- ── identity and tenancy ──────────────────────────────────────────────────\n\ncreate policy organisations_read on public.organisations\n  for select to authenticated\n  using (amryn.is_member(id) and deleted_at is null);\n\ncreate policy organisations_update on public.organisations\n  for update to authenticated\n  using (amryn.is_org_admin(id))\n  with check (amryn.is_org_admin(id));\n\n-- A user sees their own profile, plus the profiles of people they share an\n-- organisation with — needed to render owners, assignees and activity.\ncreate policy user_profiles_read on public.user_profiles\n  for select to authenticated\n  using (\n    id = auth.uid()\n    or exists (\n      select 1\n      from public.organisation_members me\n      join public.organisation_members them\n        on them.organisation_id = me.organisation_id\n      where me.user_id = auth.uid()\n        and me.status = 'active'\n        and them.user_id = public.user_profiles.id\n    )\n  );\n\ncreate policy user_profiles_write on public.user_profiles\n  for update to authenticated\n  using (id = auth.uid())\n  with check (id = auth.uid());\n\ncreate policy user_profiles_insert on public.user_profiles\n  for insert to authenticated\n  with check (id = auth.uid());\n\ncreate policy members_read on public.organisation_members\n  for select to authenticated\n  using (user_id = auth.uid() or amryn.is_member(organisation_id));\n\ncreate policy members_manage on public.organisation_members\n  for all to authenticated\n  using (amryn.has_permission(organisation_id, 'manage_users'))\n  with check (amryn.has_permission(organisation_id, 'manage_users'));\n\ncreate policy overrides_read on public.member_permission_overrides\n  for select to authenticated\n  using (amryn.is_member(organisation_id));\n\ncreate policy overrides_manage on public.member_permission_overrides\n  for all to authenticated\n  using (amryn.has_permission(organisation_id, 'manage_users'))\n  with check (amryn.has_permission(organisation_id, 'manage_users'));\n\n-- The permission catalogue is reference data: readable, never writable.\ncreate policy permissions_read on public.permissions\n  for select to authenticated using (true);\n\ncreate policy role_permissions_read on public.role_permissions\n  for select to authenticated using (true);\n\n-- ── organisational structure ──────────────────────────────────────────────\n\ncreate policy regions_read on public.regions\n  for select to authenticated\n  using (amryn.is_member(organisation_id) and deleted_at is null);\n\ncreate policy regions_manage on public.regions\n  for all to authenticated\n  using (amryn.has_permission(organisation_id, 'manage_organisation'))\n  with check (amryn.has_permission(organisation_id, 'manage_organisation'));\n\ncreate policy branches_read on public.branches\n  for select to authenticated\n  using (amryn.can_see_branch(organisation_id, id) and deleted_at is null);\n\ncreate policy branches_manage on public.branches\n  for all to authenticated\n  using (amryn.has_permission(organisation_id, 'manage_organisation'))\n  with check (amryn.has_permission(organisation_id, 'manage_organisation'));\n\ncreate policy departments_read on public.departments\n  for select to authenticated\n  using (amryn.can_see_department(organisation_id, id) and deleted_at is null);\n\ncreate policy departments_manage on public.departments\n  for all to authenticated\n  using (amryn.has_permission(organisation_id, 'manage_organisation'))\n  with check (amryn.has_permission(organisation_id, 'manage_organisation'));\n\n-- ── billing ───────────────────────────────────────────────────────────────\n\ncreate policy subscriptions_read on public.subscriptions\n  for select to authenticated\n  using (amryn.is_member(organisation_id));\n\ncreate policy subscriptions_manage on public.subscriptions\n  for all to authenticated\n  using (amryn.has_permission(organisation_id, 'manage_billing'))\n  with check (amryn.has_permission(organisation_id, 'manage_billing'));\n\ncreate policy billing_read on public.billing_records\n  for select to authenticated\n  using (amryn.has_permission(organisation_id, 'manage_billing'));\n\n-- ── audit ─────────────────────────────────────────────────────────────────\n-- Readable by administrators; append-only for everyone, and never editable.\n\ncreate policy audit_read on public.audit_logs\n  for select to authenticated\n  using (organisation_id is not null and amryn.has_permission(organisation_id, 'view_audit_log'));\n\ncreate policy audit_append on public.audit_logs\n  for insert to authenticated\n  with check (organisation_id is null or amryn.is_member(organisation_id));\n\n-- PostgREST answers from a cached copy of the schema and is not told by\n-- applying SQL. Without this, everything above exists and stays invisible to\n-- the application — which reads exactly like a migration that never ran.\nnotify pgrst, 'reload schema';\n\n-- ══════════════════════════════════════════════════════════════════════\n-- 20260829090400_05_domain_rls.sql\n-- ══════════════════════════════════════════════════════════════════════\ndo $setup$ begin raise notice 'applying 20260829090400_05_domain_rls.sql'; end $setup$;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- Amryn™ AIGrowthIntelligence® Software\n-- Migration 05 — Row Level Security for the intelligence domain\n--\n-- Most domain tables follow one of two shapes, so they are generated from a\n-- single declaration list. The list is the thing to review: it states, per\n-- table, which permission gates reading and writing and whether rows are\n-- narrowed by branch scope.\n-- ═══════════════════════════════════════════════════════════════════════════\n\ndo $$\ndeclare\n  spec record;\n  branch_clause text;\nbegin\n  for spec in\n    select *\n    from (values\n      -- table,                        read permission,          write permission,        branch-scoped\n      ('data_sources',                 'view_data_sources',      'manage_integrations',   false),\n      ('data_connections',             'view_data_sources',      'manage_integrations',   false),\n      ('data_imports',                 'view_data_sources',      'import_data',           false),\n      ('data_health_checks',           'view_data_sources',      'manage_integrations',   false),\n\n      ('business_metrics',             'view_performance',       'manage_metrics',        false),\n      ('metric_values',                'view_performance',       'import_data',           true),\n      ('financial_records',            'view_financial_data',    'import_data',           true),\n      ('sales_records',                'view_sales_data',        'import_data',           true),\n      ('operational_records',          'view_operations_data',   'import_data',           true),\n\n      ('business_health_scores',       'view_performance',       'manage_metrics',        true),\n      ('health_score_weights',         'view_performance',       'manage_metrics',        false),\n      ('business_events',              'view_intelligence',      'manage_metrics',        true),\n      ('business_insights',            'view_intelligence',      'manage_metrics',        true),\n\n      ('competitors',                  'view_competitors',       'manage_competitors',    false),\n      ('competitor_events',            'view_competitors',       'manage_competitors',    false),\n      ('market_signals',               'view_market_intelligence','manage_radar',         false),\n\n      ('opportunities',                'view_opportunities',     'manage_opportunities',  true),\n      ('opportunity_scores',           'view_opportunities',     'manage_opportunities',  false),\n      ('opportunity_score_weights',    'view_opportunities',     'manage_radar',          false),\n      ('opportunity_activities',       'view_opportunities',     'view_opportunities',    false),\n\n      ('goals',                        'view_goals',             'manage_goals',          true),\n      ('goal_progress',                'view_goals',             'manage_goals',          false),\n      ('strategic_initiatives',        'view_goals',             'manage_goals',          false),\n      ('ai_recommendations',           'view_recommendations',   'manage_recommendations',true),\n\n      ('risks',                        'view_risks',             'manage_risks',          true),\n      ('risk_events',                  'view_risks',             'manage_risks',          false),\n      ('alerts',                       'view_alerts',            'manage_alerts',         true),\n      ('reports',                      'generate_reports',       'generate_reports',      false)\n    ) as t(tbl, read_perm, write_perm, branch_scoped)\n  loop\n    branch_clause := case\n      when spec.branch_scoped then ' and amryn.can_see_branch(organisation_id, branch_id)'\n      else ''\n    end;\n\n    execute format(\n      'create policy %I on public.%I for select to authenticated using (amryn.has_permission(organisation_id, %L)%s)',\n      spec.tbl || '_read', spec.tbl, spec.read_perm, branch_clause\n    );\n\n    execute format(\n      'create policy %I on public.%I for insert to authenticated with check (amryn.has_permission(organisation_id, %L)%s)',\n      spec.tbl || '_insert', spec.tbl, spec.write_perm, branch_clause\n    );\n\n    execute format(\n      'create policy %I on public.%I for update to authenticated using (amryn.has_permission(organisation_id, %L)%s) with check (amryn.has_permission(organisation_id, %L)%s)',\n      spec.tbl || '_update', spec.tbl, spec.write_perm, branch_clause, spec.write_perm, branch_clause\n    );\n\n    execute format(\n      'create policy %I on public.%I for delete to authenticated using (amryn.has_permission(organisation_id, %L)%s)',\n      spec.tbl || '_delete', spec.tbl, spec.write_perm, branch_clause\n    );\n  end loop;\nend;\n$$;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- Tables that do not fit the pattern\n-- ═══════════════════════════════════════════════════════════════════════════\n\n-- Market sources: global catalogue rows are readable by every tenant; an\n-- organisation's own sources are private to it.\ncreate policy market_sources_read on public.market_sources\n  for select to authenticated\n  using (\n    is_global\n    or (organisation_id is not null and amryn.has_permission(organisation_id, 'view_market_intelligence'))\n  );\n\ncreate policy market_sources_manage on public.market_sources\n  for all to authenticated\n  using (organisation_id is not null and amryn.has_permission(organisation_id, 'manage_radar'))\n  with check (organisation_id is not null and amryn.has_permission(organisation_id, 'manage_radar'));\n\n-- Assignments: assignees always see their own, regardless of the wider\n-- opportunity permission, because the work has been given to them.\ncreate policy opportunity_assignments_read on public.opportunity_assignments\n  for select to authenticated\n  using (\n    assignee_id = auth.uid()\n    or amryn.has_permission(organisation_id, 'view_opportunities')\n  );\n\ncreate policy opportunity_assignments_manage on public.opportunity_assignments\n  for all to authenticated\n  using (amryn.has_permission(organisation_id, 'assign_opportunities'))\n  with check (amryn.has_permission(organisation_id, 'assign_opportunities'));\n\n-- Notifications are personal.\ncreate policy notifications_read on public.notifications\n  for select to authenticated\n  using (user_id = auth.uid());\n\ncreate policy notifications_update on public.notifications\n  for update to authenticated\n  using (user_id = auth.uid())\n  with check (user_id = auth.uid());\n\ncreate policy notifications_insert on public.notifications\n  for insert to authenticated\n  with check (amryn.is_member(organisation_id));\n\n-- Assistant threads are private to the user who held the conversation. An\n-- executive cannot read a colleague's questions.\ncreate policy ai_conversations_own on public.ai_conversations\n  for all to authenticated\n  using (user_id = auth.uid() and amryn.is_member(organisation_id))\n  with check (user_id = auth.uid() and amryn.is_member(organisation_id));\n\ncreate policy ai_messages_own on public.ai_messages\n  for all to authenticated\n  using (\n    amryn.is_member(organisation_id)\n    and exists (\n      select 1 from public.ai_conversations c\n      where c.id = ai_messages.conversation_id and c.user_id = auth.uid()\n    )\n  )\n  with check (\n    amryn.is_member(organisation_id)\n    and exists (\n      select 1 from public.ai_conversations c\n      where c.id = ai_messages.conversation_id and c.user_id = auth.uid()\n    )\n  );\n\n-- ── grants ────────────────────────────────────────────────────────────────\n-- RLS decides which rows; these decide which verbs are possible at all.\n\ngrant usage on schema public to authenticated;\ngrant select, insert, update, delete on all tables in schema public to authenticated;\ngrant usage, select on all sequences in schema public to authenticated;\n\n-- Reference tables are never written from a session.\nrevoke insert, update, delete on public.permissions from authenticated;\nrevoke insert, update, delete on public.role_permissions from authenticated;\nrevoke update, delete on public.audit_logs from authenticated;\n\n-- Nothing in this schema is reachable without a session.\nrevoke all on all tables in schema public from anon;\n\n-- PostgREST answers from a cached copy of the schema and is not told by\n-- applying SQL. Without this, everything above exists and stays invisible to\n-- the application — which reads exactly like a migration that never ran.\nnotify pgrst, 'reload schema';\n\n-- ══════════════════════════════════════════════════════════════════════\n-- 20260829090500_06_permissions_and_triggers.sql\n-- ══════════════════════════════════════════════════════════════════════\ndo $setup$ begin raise notice 'applying 20260829090500_06_permissions_and_triggers.sql'; end $setup$;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- Amryn™ AIGrowthIntelligence® Software\n-- Migration 06 — Permission catalogue, role matrix, triggers\n-- ═══════════════════════════════════════════════════════════════════════════\n\n-- Migration 04 applies `force row level security` to all 45 tables, and these\n-- two carry a select policy and nothing else. FORCE is the part that matters:\n-- ordinary RLS exempts a table's owner, FORCE does not, so these seed inserts\n-- are refused for anyone lacking BYPASSRLS — including whoever is applying the\n-- migration.\n--\n--   ERROR: new row violates row-level security policy for table \"permissions\"\n--\n-- Superusers bypass RLS unconditionally, so a local PostgreSQL never showed\n-- it. Whether a hosted project does depends on whether its role happens to\n-- carry BYPASSRLS, which is not a thing to build a schema on.\n--\n-- FORCE is lifted for the length of the seed and restored immediately. Both\n-- statements are inside the migration's transaction, so there is no window in\n-- which the tables are deployed unprotected.\n--\n-- These two are a fixed catalogue, not tenant data: every organisation reads\n-- the same rows, which is why a select policy is all they ever needed.\nalter table public.permissions      no force row level security;\nalter table public.role_permissions no force row level security;\n\ninsert into public.permissions (key, category, description) values\n  ('view_performance',        'Performance',    'View business performance dashboards and metrics'),\n  ('view_financial_data',     'Performance',    'View revenue, cost, margin and cash figures'),\n  ('view_sales_data',         'Performance',    'View sales records, customers and pipeline value'),\n  ('view_operations_data',    'Performance',    'View operational measures such as delivery and utilisation'),\n  ('view_intelligence',       'Intelligence',   'View AI DigitalTwin® findings, events and insights'),\n  ('view_market_intelligence','Intelligence',   'View external market signals'),\n  ('view_competitors',        'Intelligence',   'View tracked competitors and their activity'),\n  ('view_opportunities',      'Opportunities',  'View the opportunity pipeline and radar'),\n  ('assign_opportunities',    'Opportunities',  'Assign opportunities to colleagues'),\n  ('manage_opportunities',    'Opportunities',  'Create, edit and progress opportunities'),\n  ('view_recommendations',    'Strategy',       'View AI recommendations'),\n  ('manage_recommendations',  'Strategy',       'Accept, dismiss and progress recommendations'),\n  ('view_goals',              'Strategy',       'View goals and strategic initiatives'),\n  ('manage_goals',            'Strategy',       'Create and edit goals and initiatives'),\n  ('view_risks',              'Risk',           'View the risk register and risk dashboard'),\n  ('manage_risks',            'Risk',           'Raise, reassess and close risks'),\n  ('view_alerts',             'Risk',           'View alerts'),\n  ('manage_alerts',           'Risk',           'Acknowledge, assign, snooze and dismiss alerts'),\n  ('view_data_sources',       'Data',           'View connected sources, imports and data health'),\n  ('import_data',             'Data',           'Upload and import business data'),\n  ('manage_integrations',     'Data',           'Create and configure data connections'),\n  ('manage_metrics',          'Data',           'Define metrics and health-score weighting'),\n  ('manage_competitors',      'Intelligence',   'Add and edit tracked competitors'),\n  ('manage_radar',            'Intelligence',   'Configure market sources and radar scoring'),\n  ('generate_reports',        'Reporting',      'Generate and export reports'),\n  ('use_ai_assistant',        'Intelligence',   'Ask the Amryn AI Assistant questions'),\n  ('view_audit_log',          'Administration', 'Read the organisation audit trail'),\n  ('manage_users',            'Administration', 'Invite, edit and remove members and permissions'),\n  ('manage_organisation',     'Administration', 'Edit the organisation, regions, branches and departments'),\n  ('manage_billing',          'Administration', 'View and change the subscription and billing details');\n\n-- ── role matrix ───────────────────────────────────────────────────────────\n-- Reach widens down the list; scope (which branches a member sees) is a\n-- separate axis, applied by RLS on top of these grants.\n\ndo $$\ndeclare\n  everything text[] := array(select key from public.permissions order by key);\n\n  viewer text[] := array[\n    'view_performance','view_intelligence','view_market_intelligence','view_competitors',\n    'view_opportunities','view_recommendations','view_goals','view_alerts','use_ai_assistant'\n  ];\n\n  department_manager text[] := viewer || array[\n    'view_sales_data','view_operations_data','view_risks','view_data_sources',\n    'manage_goals','manage_alerts','generate_reports'\n  ];\n\n  branch_manager text[] := department_manager || array[\n    'view_financial_data','manage_opportunities','manage_recommendations','manage_risks','import_data'\n  ];\n\n  regional_manager text[] := branch_manager || array[\n    'assign_opportunities','view_audit_log'\n  ];\n\n  analyst text[] := array[\n    'view_performance','view_financial_data','view_sales_data','view_operations_data',\n    'view_intelligence','view_market_intelligence','view_competitors','view_opportunities',\n    'view_recommendations','view_goals','view_risks','view_alerts','view_data_sources',\n    'import_data','manage_metrics','generate_reports','use_ai_assistant'\n  ];\n\n  -- The executive view is the whole business, minus the plumbing that\n  -- administrators and analysts own.\n  executive text[] := regional_manager || array[\n    'manage_competitors','manage_radar','manage_users'\n  ];\nbegin\n  insert into public.role_permissions (role, permission_key)\n  select 'super_admin'::public.org_role, unnest(everything)\n  union all select 'org_admin', unnest(everything)\n  union all select 'executive', unnest(executive)\n  union all select 'regional_manager', unnest(regional_manager)\n  union all select 'branch_manager', unnest(branch_manager)\n  union all select 'department_manager', unnest(department_manager)\n  union all select 'analyst', unnest(analyst)\n  union all select 'viewer', unnest(viewer)\n  on conflict do nothing;\nend;\n$$;\n\n-- Protection restored before anything else runs.\nalter table public.permissions      force row level security;\nalter table public.role_permissions force row level security;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- Triggers\n-- ═══════════════════════════════════════════════════════════════════════════\n\ncreate or replace function amryn.touch_updated_at()\nreturns trigger\nlanguage plpgsql\nas $$\nbegin\n  new.updated_at := now();\n  return new;\nend;\n$$;\n\ndo $$\ndeclare\n  t text;\nbegin\n  foreach t in array array[\n    'organisations','user_profiles','regions','branches','departments',\n    'organisation_members','subscriptions','data_sources','data_connections',\n    'business_metrics','competitors','opportunities','goals',\n    'strategic_initiatives','ai_recommendations','risks','ai_conversations'\n  ]\n  loop\n    execute format(\n      'create trigger %I before update on public.%I for each row execute function amryn.touch_updated_at()',\n      t || '_touch', t\n    );\n  end loop;\nend;\n$$;\n\n-- Mirror new auth users into user_profiles so the app always has a profile to\n-- render, without a first-login write path that could fail.\ncreate or replace function amryn.handle_new_user()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\nbegin\n  insert into public.user_profiles (id, email, full_name, avatar_url)\n  values (\n    new.id,\n    new.email,\n    coalesce(new.raw_user_meta_data ->> 'full_name', new.raw_user_meta_data ->> 'name'),\n    new.raw_user_meta_data ->> 'avatar_url'\n  )\n  on conflict (id) do update\n    set email = excluded.email,\n        full_name = coalesce(public.user_profiles.full_name, excluded.full_name);\n  return new;\nend;\n$$;\n\n-- Guarded, because creating a trigger requires owning the table and on a\n-- hosted Supabase project auth.users belongs to supabase_auth_admin rather\n-- than the role applying this file. Unguarded, this one statement failed the\n-- entire migration — taking the permission catalogue, the role matrix and\n-- create_organisation down with it, and leaving a database that looked like\n-- the migrations had never run.\n--\n-- Where the trigger cannot be installed, public.ensure_user_profile() in\n-- migration 10 does the same work on first sign-in instead.\ndo $$\nbegin\n  create trigger on_auth_user_created\n    after insert on auth.users\n    for each row execute function amryn.handle_new_user();\nexception\n  when insufficient_privilege then\n    raise notice 'not permitted to add a trigger to auth.users; profiles are created on first sign-in instead';\n  when duplicate_object then\n    raise notice 'profile trigger already present';\nend;\n$$;\n\n-- Risk severity is derived from likelihood × impact, but stored, so that a\n-- later change to the scale does not silently rewrite history.\ncreate or replace function amryn.derive_risk_severity()\nreturns trigger\nlanguage plpgsql\nas $$\ndeclare\n  product integer := new.likelihood * new.impact;\nbegin\n  new.severity := case\n    when product >= 20 then 'critical'::public.priority_level\n    when product >= 12 then 'high'::public.priority_level\n    when product >= 6  then 'medium'::public.priority_level\n    else 'low'::public.priority_level\n  end;\n  return new;\nend;\n$$;\n\ncreate trigger risks_derive_severity\n  before insert or update of likelihood, impact on public.risks\n  for each row execute function amryn.derive_risk_severity();\n\n-- ── organisation bootstrap ────────────────────────────────────────────────\n-- Creating an organisation from the app is a single call: it must also create\n-- the caller's membership, the subscription and the default weighting, or none\n-- of it. SECURITY DEFINER because the caller is not yet a member of the\n-- organisation whose rows are being written.\n\ncreate or replace function public.create_organisation(\n  p_name text,\n  p_slug text,\n  p_industry text default null,\n  p_country_code char(2) default 'ZA',\n  p_currency_code char(3) default 'ZAR'\n)\nreturns uuid\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  new_org uuid;\n  uid uuid := auth.uid();\nbegin\n  if uid is null then\n    raise exception 'authentication required' using errcode = '42501';\n  end if;\n\n  insert into public.organisations (name, slug, industry, country_code, currency_code)\n  values (p_name, lower(p_slug), p_industry, upper(p_country_code), upper(p_currency_code))\n  returning id into new_org;\n\n  insert into public.organisation_members (organisation_id, user_id, role, status, scope_kind)\n  values (new_org, uid, 'org_admin', 'active', 'organisation');\n\n  insert into public.subscriptions (organisation_id, plan, status, trial_ends_at)\n  values (new_org, 'starter', 'trialing', now() + interval '30 days');\n\n  insert into public.health_score_weights (organisation_id, category, weight) values\n    (new_org, 'financial',   0.25),\n    (new_org, 'operational', 0.20),\n    (new_org, 'sales',       0.20),\n    (new_org, 'growth',      0.15),\n    (new_org, 'customer',    0.10),\n    (new_org, 'strategic',   0.10);\n\n  insert into public.opportunity_score_weights (organisation_id) values (new_org);\n\n  insert into public.audit_logs (organisation_id, actor_id, action, entity_type, entity_id, summary)\n  values (new_org, uid, 'organisation.created', 'organisation', new_org::text, p_name);\n\n  return new_org;\nend;\n$$;\n\nrevoke all on function public.create_organisation(text, text, text, char, char) from public, anon;\ngrant execute on function public.create_organisation(text, text, text, char, char) to authenticated;\n\n-- Health-score weights must sum to 1 for the score to be a true weighted mean.\ncreate or replace function amryn.assert_health_weights_sum()\nreturns trigger\nlanguage plpgsql\nas $$\ndeclare\n  total numeric;\n  org uuid := coalesce(new.organisation_id, old.organisation_id);\nbegin\n  select sum(weight) into total\n    from public.health_score_weights\n   where organisation_id = org;\n\n  if total is not null and abs(total - 1) > 0.001 then\n    raise exception 'health score weights for organisation % sum to %, expected 1', org, total;\n  end if;\n  return null;\nend;\n$$;\n\ncreate constraint trigger health_weights_sum_to_one\n  after insert or update or delete on public.health_score_weights\n  deferrable initially deferred\n  for each row execute function amryn.assert_health_weights_sum();\n\n-- PostgREST answers from a cached copy of the schema and is not told by\n-- applying SQL. Without this, everything above exists and stays invisible to\n-- the application — which reads exactly like a migration that never ran.\nnotify pgrst, 'reload schema';\n\n-- ══════════════════════════════════════════════════════════════════════\n-- 20260830080000_07_sector_policy.sql\n-- ══════════════════════════════════════════════════════════════════════\ndo $setup$ begin raise notice 'applying 20260830080000_07_sector_policy.sql'; end $setup$;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- Amryn™ AIGrowthIntelligence® Software\n-- Migration 07 — Sector policy belongs to the customer, not to the platform\n--\n-- Migration 03 defaulted market scanning to the private sector alone and the\n-- recommendation layer refused to surface tenders at all. That conflated two\n-- different things:\n--\n--   · Amryn's own commercial posture — the company does not take on\n--     government-sector business. That is a fact about who Amryn sells to,\n--     and it belongs in the company's positioning, not in a WHERE clause.\n--\n--   · What an Amryn customer should be shown. Customers are private\n--     businesses, and a municipal supply tender is ordinary revenue to a\n--     wholesaler. Filtering it out withheld real money from the people\n--     paying for the product.\n--\n-- So sector scope becomes an explicit, per-organisation setting. The default\n-- is to surface everything and let relevance and strategic alignment decide\n-- what ranks — which is what those factors are for. An organisation that does\n-- not pursue public-sector work narrows the setting once, and the radar\n-- honours it everywhere.\n-- ═══════════════════════════════════════════════════════════════════════════\n\n-- A tender is its own kind of opportunity: a defined scope, a published\n-- deadline and a competitive submission. Modelling it as 'market_expansion'\n-- lost the shape that makes it actionable.\nalter type public.opportunity_kind add value if not exists 'tender';\n\n-- ── per-organisation sector scope ─────────────────────────────────────────\n-- Which sectors this organisation wants its radar to surface. Defaults to all\n-- of them: an opportunity is filtered out only because a customer chose to\n-- filter it, never because the platform decided on their behalf.\n\nalter table public.organisations\n  add column if not exists sector_scope public.market_sector[]\n    not null default '{private,public,mixed,unknown}';\n\ncomment on column public.organisations.sector_scope is\n  'Sectors the AI OpportunityRadar® may surface for this organisation. Set by the customer. Amryn''s own commercial posture is not encoded here.';\n\nalter table public.organisations\n  add constraint sector_scope_not_empty check (cardinality(sector_scope) > 0);\n\n-- Existing market sources were seeded private-only by the previous default.\n-- Widen them to match the new posture; a customer narrows from here.\nalter table public.market_sources\n  alter column sector_policy set default '{private,public,mixed,unknown}';\n\nupdate public.market_sources\n   set sector_policy = '{private,public,mixed,unknown}'\n where sector_policy = '{private}';\n\n-- ── honouring the setting ─────────────────────────────────────────────────\n-- Enforced in the database rather than only in the query layer, so a report,\n-- an export and the assistant all see the same set. A row outside the\n-- organisation's chosen scope is simply not selectable.\n\ncreate or replace function amryn.sector_in_scope(p_org uuid, p_sector public.market_sector)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = public, pg_temp\nas $$\n  select coalesce(\n    (select p_sector = any (o.sector_scope) from public.organisations o where o.id = p_org),\n    false\n  );\n$$;\n\ngrant execute on function amryn.sector_in_scope(uuid, public.market_sector) to authenticated;\n\ndrop policy if exists opportunities_read on public.opportunities;\ncreate policy opportunities_read on public.opportunities\n  for select to authenticated\n  using (\n    amryn.has_permission(organisation_id, 'view_opportunities')\n    and amryn.can_see_branch(organisation_id, branch_id)\n    and amryn.sector_in_scope(organisation_id, sector)\n  );\n\ndrop policy if exists market_signals_read on public.market_signals;\ncreate policy market_signals_read on public.market_signals\n  for select to authenticated\n  using (\n    amryn.has_permission(organisation_id, 'view_market_intelligence')\n    and amryn.sector_in_scope(organisation_id, sector)\n  );\n\n-- PostgREST answers from a cached copy of the schema and is not told by\n-- applying SQL. Without this, everything above exists and stays invisible to\n-- the application — which reads exactly like a migration that never ran.\nnotify pgrst, 'reload schema';\n\n-- ══════════════════════════════════════════════════════════════════════\n-- 20260830190000_08_organisation_bootstrap_rpc.sql\n-- ══════════════════════════════════════════════════════════════════════\ndo $setup$ begin raise notice 'applying 20260830190000_08_organisation_bootstrap_rpc.sql'; end $setup$;\n\n-- ── organisation bootstrap, made reachable ────────────────────────────────\n--\n-- Symptom this fixes, seen on the live deployment at /onboarding:\n--\n--   Could not find the function public.create_organisation(p_country_code,\n--   p_currency_code, p_industry, p_name, p_slug) in the schema cache\n--\n-- PostgREST resolves a remote call against a cache of the schema, not against\n-- the schema. Three separate things produce that one message, and the reader\n-- cannot tell them apart:\n--\n--   1. The function is genuinely absent — migration 06 was never applied.\n--   2. It exists, but PostgREST last built its cache before it did. Applying\n--      migrations through the SQL editor does not reload that cache, so a\n--      correct database serves a stale answer indefinitely.\n--   3. It exists, but the caller's arguments cannot be coerced to its\n--      parameter types, so no candidate matches.\n--\n-- This migration settles all three, and is safe to run whether or not 06 was.\n--\n-- On (3): the parameters were char(2) and char(3). A blank-padded fixed-width\n-- type is a poor thing to expose over an interface that sends everything as\n-- JSON text, and it buys nothing here — the columns are still char(2)/char(3)\n-- with their own check constraints, so the storage guarantee is unchanged.\n-- The parameters become text, and the function validates them itself so a bad\n-- value is a sentence rather than a silent truncation.\n--\n-- A type change cannot be made with `create or replace`: Postgres treats a\n-- different parameter type as a different function and would leave both in\n-- place. Two candidates with identical argument names is worse than none —\n-- PostgREST then fails as ambiguous. So both signatures are dropped first.\n\ndrop function if exists public.create_organisation(text, text, text, char, char);\ndrop function if exists public.create_organisation(text, text, text, text, text);\n\ncreate function public.create_organisation(\n  p_name text,\n  p_slug text,\n  p_industry text default null,\n  p_country_code text default 'ZA',\n  p_currency_code text default 'ZAR'\n)\nreturns uuid\nlanguage plpgsql\nsecurity definer\n-- SECURITY DEFINER because the caller is not yet a member of the organisation\n-- whose rows are being written. search_path is pinned so the elevated body\n-- cannot be redirected to a caller-controlled schema.\nset search_path = public, pg_temp\nas $$\ndeclare\n  new_org  uuid;\n  uid      uuid := auth.uid();\n  country  text := upper(btrim(coalesce(p_country_code, 'ZA')));\n  currency text := upper(btrim(coalesce(p_currency_code, 'ZAR')));\nbegin\n  if uid is null then\n    raise exception 'authentication required' using errcode = '42501';\n  end if;\n\n  -- Validated here rather than left to the column cast. char(2) silently\n  -- truncates anything longer, so 'ZAF' would have been stored as 'ZA' and\n  -- nobody would have been told.\n  if length(country) <> 2 then\n    raise exception 'country code must be two letters, got %', country\n      using errcode = '22023';\n  end if;\n\n  if length(currency) <> 3 then\n    raise exception 'currency code must be three letters, got %', currency\n      using errcode = '22023';\n  end if;\n\n  insert into public.organisations (name, slug, industry, country_code, currency_code)\n  values (p_name, lower(p_slug), p_industry, country, currency)\n  returning id into new_org;\n\n  insert into public.organisation_members (organisation_id, user_id, role, status, scope_kind)\n  values (new_org, uid, 'org_admin', 'active', 'organisation');\n\n  insert into public.subscriptions (organisation_id, plan, status, trial_ends_at)\n  values (new_org, 'starter', 'trialing', now() + interval '30 days');\n\n  insert into public.health_score_weights (organisation_id, category, weight) values\n    (new_org, 'financial',   0.25),\n    (new_org, 'operational', 0.20),\n    (new_org, 'sales',       0.20),\n    (new_org, 'growth',      0.15),\n    (new_org, 'customer',    0.10),\n    (new_org, 'strategic',   0.10);\n\n  insert into public.opportunity_score_weights (organisation_id) values (new_org);\n\n  insert into public.audit_logs (organisation_id, actor_id, action, entity_type, entity_id, summary)\n  values (new_org, uid, 'organisation.created', 'organisation', new_org::text, p_name);\n\n  return new_org;\nend;\n$$;\n\n-- anon must never reach this: it writes an organisation and an admin\n-- membership, and it runs as its owner.\nrevoke all on function public.create_organisation(text, text, text, text, text) from public, anon;\ngrant execute on function public.create_organisation(text, text, text, text, text) to authenticated;\n\n-- Cause (2). Without this the function above exists and stays invisible over\n-- the API until something else happens to reload the cache.\nnotify pgrst, 'reload schema';\n\n-- ══════════════════════════════════════════════════════════════════════\n-- 20260830200000_09_default_privileges.sql\n-- ══════════════════════════════════════════════════════════════════════\ndo $setup$ begin raise notice 'applying 20260830200000_09_default_privileges.sql'; end $setup$;\n\n-- ── privileges for tables added later ─────────────────────────────────────\n--\n-- Migration 05 grants `authenticated` its table privileges with\n-- `grant ... on all tables in schema public`. That phrasing is a snapshot: it\n-- covers the tables existing at the moment it runs, and says nothing about any\n-- added afterwards. A table created by a future migration would therefore be\n-- unreachable by every signed-in user, and PostgREST would report it as\n-- missing from the schema cache rather than as a privilege problem — which is\n-- a long way from the cause.\n--\n-- Default privileges close that, so the grant applies to what does not exist\n-- yet.\n--\n-- Deliberately nothing for `anon`. It holds no privilege on these tables and\n-- should not: every one of the 45 policies targets `authenticated`, so Row\n-- Level Security alone would already return an anonymous caller nothing, and\n-- withholding the grant as well means a policy misconfigured tomorrow still\n-- cannot leak to an anonymous request. 10_rls_isolation_test.sql asserts that\n-- second wall is standing.\n\nalter default privileges in schema public\n  grant select, insert, update, delete on tables to authenticated;\n\nalter default privileges in schema public\n  grant usage, select on sequences to authenticated;\n\nnotify pgrst, 'reload schema';\n\n-- ══════════════════════════════════════════════════════════════════════\n-- 20260830210000_10_profile_without_auth_trigger.sql\n-- ══════════════════════════════════════════════════════════════════════\ndo $setup$ begin raise notice 'applying 20260830210000_10_profile_without_auth_trigger.sql'; end $setup$;\n\n-- ── surviving a trigger that cannot be created ────────────────────────────\n--\n-- Migration 06 ends with:\n--\n--   create trigger on_auth_user_created after insert on auth.users ...\n--\n-- Creating a trigger requires ownership of the table, and on a hosted Supabase\n-- project auth.users belongs to supabase_auth_admin, not to the role the SQL\n-- editor runs as. Whether that succeeds depends on the vintage of the project;\n-- on the ones where it does not, it fails with\n--\n--   ERROR: 42501: must be owner of relation users\n--\n-- and because the editor runs each script in a transaction, the whole of\n-- migration 06 rolls back — the permission catalogue, the role matrix and\n-- create_organisation with it. The database is then left with every table and\n-- policy in place and none of its seed data, which reads exactly like\n-- migrations that were never applied.\n--\n-- A local PostgreSQL owns everything, so the suite never saw it.\n--\n-- Rather than depend on knowing which kind of project this is, the trigger\n-- becomes optional and its work is made reachable another way.\n\n-- 1. Never let this be the statement that fails a migration.\ndo $$\nbegin\n  create trigger on_auth_user_created\n    after insert on auth.users\n    for each row execute function amryn.handle_new_user();\n  raise notice 'profile trigger installed on auth.users';\nexception\n  when insufficient_privilege then\n    raise notice 'not permitted to add a trigger to auth.users on this project; profiles are created on first sign-in instead';\n  when duplicate_object then\n    raise notice 'profile trigger already present';\nend;\n$$;\n\n-- 2. The first-login write path the trigger existed to avoid needing.\n--\n-- SECURITY DEFINER so it can read auth.users, which the caller cannot. It acts\n-- only on auth.uid(), so a caller can create a profile for themselves and for\n-- nobody else — there is no parameter to point at another user.\ncreate or replace function public.ensure_user_profile()\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  uid uuid := auth.uid();\nbegin\n  if uid is null then\n    return;\n  end if;\n\n  insert into public.user_profiles (id, email, full_name, avatar_url)\n  select\n    u.id,\n    u.email,\n    coalesce(u.raw_user_meta_data ->> 'full_name', u.raw_user_meta_data ->> 'name'),\n    u.raw_user_meta_data ->> 'avatar_url'\n  from auth.users u\n  where u.id = uid\n  on conflict (id) do update\n    set email = excluded.email,\n        full_name = coalesce(public.user_profiles.full_name, excluded.full_name);\nend;\n$$;\n\nrevoke all on function public.ensure_user_profile() from public, anon;\ngrant execute on function public.ensure_user_profile() to authenticated;\n\n-- 3. Anyone who signed up while the trigger was absent has no profile. Backfill\n-- them, so this migration repairs the accounts it was too late to prevent.\ninsert into public.user_profiles (id, email, full_name, avatar_url)\nselect\n  u.id,\n  u.email,\n  coalesce(u.raw_user_meta_data ->> 'full_name', u.raw_user_meta_data ->> 'name'),\n  u.raw_user_meta_data ->> 'avatar_url'\nfrom auth.users u\non conflict (id) do nothing;\n\nnotify pgrst, 'reload schema';\n\n-- ══════════════════════════════════════════════════════════════════════\n-- 20260831090000_11_invitations.sql\n-- ══════════════════════════════════════════════════════════════════════\ndo $setup$ begin raise notice 'applying 20260831090000_11_invitations.sql'; end $setup$;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- Amryn™ AIGrowthIntelligence® Software\n-- Migration 11 — Invitations\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- Until now every person who signed up got an organisation of their own, and\n-- there was no way into anyone else's. The members screen already rendered an\n-- `invited` status and nothing ever wrote one.\n--\n-- The obvious implementation does not work: organisation_members.user_id\n-- references auth.users and is not null, so a membership cannot exist for\n-- somebody who has not signed up yet — which is exactly who an invitation is\n-- for. So an invitation is its own record, and becomes a membership when it is\n-- accepted.\n--\n-- The link is the credential, so it is treated as one. Only a SHA-256 hash of\n-- the token is stored: the database never holds anything that grants access,\n-- and a leaked backup does not let anyone in. The raw token exists once, in the\n-- response that creates it, and is shown to the person who will send it on.\n\ncreate table public.organisation_invitations (\n  id              uuid primary key default gen_random_uuid(),\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  -- citext, so an invitation to Someone@Example.com is accepted by\n  -- someone@example.com. Case-sensitivity here would be a support burden and\n  -- protects nothing.\n  email           citext not null,\n  role            public.org_role not null default 'viewer',\n  scope_kind      public.scope_kind not null default 'organisation',\n  scope_ids       uuid[] not null default '{}',\n  -- Never the token itself.\n  token_hash      text not null unique,\n  invited_by      uuid references auth.users (id) on delete set null,\n  expires_at      timestamptz not null default now() + interval '14 days',\n  accepted_at     timestamptz,\n  accepted_by     uuid references auth.users (id) on delete set null,\n  revoked_at      timestamptz,\n  created_at      timestamptz not null default now(),\n  updated_at      timestamptz not null default now(),\n\n  constraint scope_ids_match_kind check (\n    (scope_kind = 'organisation' and cardinality(scope_ids) = 0)\n    or (scope_kind <> 'organisation' and cardinality(scope_ids) > 0)\n  ),\n  -- An invitation is either open, accepted or revoked. Recording both an\n  -- acceptance and a revocation would leave no answer to \"did they get in\".\n  constraint not_both_accepted_and_revoked check (\n    accepted_at is null or revoked_at is null\n  )\n);\n\n-- One open invitation per address per organisation. A partial index rather than\n-- a plain unique constraint, so the same person can be re-invited after an\n-- invitation is revoked or expires.\ncreate unique index organisation_invitations_open_email\n  on public.organisation_invitations (organisation_id, email)\n  where accepted_at is null and revoked_at is null;\n\ncreate index organisation_invitations_org on public.organisation_invitations (organisation_id);\n\ncreate trigger organisation_invitations_touch\n  before update on public.organisation_invitations\n  for each row execute function amryn.touch_updated_at();\n\n-- ── who may see and write them ────────────────────────────────────────────\nalter table public.organisation_invitations enable row level security;\nalter table public.organisation_invitations force row level security;\n\n-- Reading an invitation reveals who is being brought into the business, so it\n-- is limited to the people who manage members — not every colleague.\ncreate policy organisation_invitations_read on public.organisation_invitations\n  for select to authenticated\n  using (amryn.has_permission(organisation_id, 'manage_users'));\n\ncreate policy organisation_invitations_write on public.organisation_invitations\n  for insert to authenticated\n  with check (amryn.has_permission(organisation_id, 'manage_users'));\n\n-- Update covers revoking. Acceptance does not come through here: the invitee\n-- is not a member yet and no policy would let them touch the row, which is why\n-- accept_invitation() runs as its owner.\ncreate policy organisation_invitations_update on public.organisation_invitations\n  for update to authenticated\n  using (amryn.has_permission(organisation_id, 'manage_users'))\n  with check (amryn.has_permission(organisation_id, 'manage_users'));\n\ngrant select, insert, update on public.organisation_invitations to authenticated;\n\n-- ── looking at an invitation before accepting it ──────────────────────────\n--\n-- The invitee cannot read the row — they are not a member of anything yet — so\n-- this reads it for them and returns only what the page needs to say: which\n-- organisation, which role, and whether the link is still good. Not who else\n-- is invited, and not the token.\n--\n-- Takes the raw token, so possession of the link is the whole authorisation.\ncreate or replace function public.invitation_preview(p_token text)\nreturns table (\n  organisation_name text,\n  role              public.org_role,\n  email             text,\n  state             text\n)\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  hashed text := encode(digest(coalesce(p_token, ''), 'sha256'), 'hex');\n  -- Not named `found`: that is PL/pgSQL's own boolean, and shadowing it makes\n  -- `if not found` a type error rather than the check it looks like.\n  invite record;\nbegin\n  select i.*, o.name as org_name\n    into invite\n    from public.organisation_invitations i\n    join public.organisations o on o.id = i.organisation_id\n   where i.token_hash = hashed;\n\n  if invite.id is null then\n    -- Deliberately indistinguishable from an expired one on the caller's side:\n    -- a separate \"no such invitation\" would make this a way to test tokens.\n    return query select null::text, null::public.org_role, null::text, 'invalid'::text;\n    return;\n  end if;\n\n  return query select\n    invite.org_name::text,\n    invite.role,\n    invite.email::text,\n    case\n      when invite.revoked_at is not null then 'revoked'\n      when invite.accepted_at is not null then 'accepted'\n      when invite.expires_at <= now() then 'expired'\n      else 'open'\n    end;\nend;\n$$;\n\nrevoke all on function public.invitation_preview(text) from public;\n-- anon may call it: someone following an invitation link has usually not\n-- signed in yet, and being told what they are being invited to is the point.\ngrant execute on function public.invitation_preview(text) to anon, authenticated;\n\n-- ── accepting ─────────────────────────────────────────────────────────────\n--\n-- SECURITY DEFINER because the caller is, by definition, not yet a member of\n-- the organisation whose membership row is about to be written — the same\n-- reason create_organisation() runs this way.\n--\n-- The membership is created with the role and scope recorded on the\n-- invitation, never with anything the caller sends. There is no parameter here\n-- but the token.\ncreate or replace function public.accept_invitation(p_token text)\nreturns uuid\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  uid        uuid := auth.uid();\n  user_email citext;\n  invite     public.organisation_invitations;\nbegin\n  if uid is null then\n    raise exception 'authentication required' using errcode = '42501';\n  end if;\n\n  select u.email into user_email from auth.users u where u.id = uid;\n\n  select * into invite\n    from public.organisation_invitations\n   where token_hash = encode(digest(coalesce(p_token, ''), 'sha256'), 'hex')\n     for update;\n\n  if not found then\n    raise exception 'this invitation link is not valid' using errcode = '22023';\n  end if;\n\n  if invite.revoked_at is not null then\n    raise exception 'this invitation has been withdrawn' using errcode = '22023';\n  end if;\n\n  if invite.expires_at <= now() then\n    raise exception 'this invitation has expired' using errcode = '22023';\n  end if;\n\n  -- Bound to the address it was sent to. Holding the link is not enough:\n  -- a forwarded invitation would otherwise hand a stranger access to the\n  -- company's data under someone else's name.\n  if user_email is null or user_email <> invite.email then\n    raise exception 'this invitation was sent to a different email address'\n      using errcode = '42501';\n  end if;\n\n  -- Already accepted is only an error if somebody else accepted it. For the\n  -- same person it is a repeated click, and the answer is where they were\n  -- going anyway.\n  if invite.accepted_at is not null then\n    if invite.accepted_by = uid then\n      return invite.organisation_id;\n    end if;\n    raise exception 'this invitation has already been used' using errcode = '22023';\n  end if;\n\n  insert into public.organisation_members\n    (organisation_id, user_id, role, status, scope_kind, scope_ids, invited_by, invited_at)\n  values\n    (invite.organisation_id, uid, invite.role, 'active', invite.scope_kind,\n     invite.scope_ids, invite.invited_by, invite.created_at)\n  on conflict (organisation_id, user_id) do update\n    set status = 'active';\n\n  update public.organisation_invitations\n     set accepted_at = now(), accepted_by = uid\n   where id = invite.id;\n\n  insert into public.audit_logs\n    (organisation_id, actor_id, action, entity_type, entity_id, summary)\n  values\n    (invite.organisation_id, uid, 'member.joined', 'organisation_member', uid::text,\n     invite.email || ' accepted an invitation as ' || invite.role);\n\n  return invite.organisation_id;\nend;\n$$;\n\nrevoke all on function public.accept_invitation(text) from public, anon;\ngrant execute on function public.accept_invitation(text) to authenticated;\n\nnotify pgrst, 'reload schema';\n\n-- ══════════════════════════════════════════════════════════════════════\n-- 20260831120000_12_rate_limits.sql\n-- ══════════════════════════════════════════════════════════════════════\ndo $setup$ begin raise notice 'applying 20260831120000_12_rate_limits.sql'; end $setup$;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- Amryn™ AIGrowthIntelligence® Software\n-- Migration 12 — Rate limiting\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- Sign-in, sign-up, organisation creation and invitations had no limit on how\n-- often they could be attempted. That is a credential-stuffing surface on the\n-- first two and, on the last, a way for one administrator to issue unbounded\n-- invitations.\n--\n-- In the database rather than in memory, because the application runs as\n-- serverless functions: an in-memory counter is per-instance, resets whenever\n-- one is recycled, and counts nothing at all once there is more than one.\n--\n-- ── what is stored ────────────────────────────────────────────────────────\n-- Only a hash. The thing being limited is an email address or an IP address,\n-- and both are personal information under POPIA — keeping either in readable\n-- form would mean a table of who tried to sign in and from where, retained for\n-- no purpose the person consented to. A SHA-256 of the identifier answers\n-- \"has this one been seen too often\" without recording whose it is.\n\ncreate table public.rate_limits (\n  -- The hash is the identity of the bucket; there is nothing else to key on.\n  bucket      text primary key,\n  attempts    integer not null default 0,\n  -- When the current window began. A window is a fixed period from the first\n  -- attempt, not a sliding one: simpler to reason about, and the difference\n  -- does not matter at the resolution of a login form.\n  window_start timestamptz not null default now(),\n  updated_at   timestamptz not null default now()\n);\n\ncreate index rate_limits_window_start on public.rate_limits (window_start);\n\n-- Locked down completely. Nothing reads or writes this except the function\n-- below, which runs as its owner: the counts are not the application's\n-- business, and a client that could read them could enumerate activity.\nalter table public.rate_limits enable row level security;\nalter table public.rate_limits force row level security;\nrevoke all on public.rate_limits from public, anon, authenticated;\n\n-- ── the check ─────────────────────────────────────────────────────────────\n--\n-- Returns true when the attempt is allowed. Atomic: the insert-on-conflict is\n-- a single statement, so two requests arriving together cannot both read a\n-- count of four and both decide they are the fifth.\n--\n-- Callable by anon, because sign-in and sign-up are attempted before anyone is\n-- authenticated. It takes an already-hashed key, so the raw address never\n-- travels to the database and never appears in a query log.\ncreate or replace function public.check_rate_limit(\n  p_bucket   text,\n  p_max      integer,\n  p_window   interval\n)\nreturns boolean\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  current_attempts integer;\nbegin\n  if p_bucket is null or length(p_bucket) = 0 then\n    -- Nothing to key on. Allowing it is the right failure: a rate limiter that\n    -- refuses when it cannot identify the caller locks everyone out.\n    return true;\n  end if;\n\n  insert into public.rate_limits (bucket, attempts, window_start, updated_at)\n  values (p_bucket, 1, now(), now())\n  on conflict (bucket) do update\n    set\n      -- Past the window, the count starts again rather than accumulating\n      -- forever.\n      attempts = case\n        when public.rate_limits.window_start < now() - p_window then 1\n        else public.rate_limits.attempts + 1\n      end,\n      window_start = case\n        when public.rate_limits.window_start < now() - p_window then now()\n        else public.rate_limits.window_start\n      end,\n      updated_at = now()\n  returning attempts into current_attempts;\n\n  return current_attempts <= p_max;\nend;\n$$;\n\nrevoke all on function public.check_rate_limit(text, integer, interval) from public;\ngrant execute on function public.check_rate_limit(text, integer, interval) to anon, authenticated;\n\n-- ── housekeeping ──────────────────────────────────────────────────────────\n--\n-- Rows outlive their usefulness the moment their window closes. Keeping them\n-- would turn a counter into a log of attempts, which is the thing this table\n-- was designed not to be.\ncreate or replace function public.prune_rate_limits()\nreturns integer\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  removed integer;\nbegin\n  delete from public.rate_limits where window_start < now() - interval '1 day';\n  get diagnostics removed = row_count;\n  return removed;\nend;\n$$;\n\nrevoke all on function public.prune_rate_limits() from public, anon, authenticated;\n\nnotify pgrst, 'reload schema';\n\n-- ══════════════════════════════════════════════════════════════════════\n-- 20260831140000_13_consent_and_data_rights.sql\n-- ══════════════════════════════════════════════════════════════════════\ndo $setup$ begin raise notice 'applying 20260831140000_13_consent_and_data_rights.sql'; end $setup$;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- Amryn™ AIGrowthIntelligence® Software\n-- Migration 13 — Consent, and the right to ask what is held\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- POPIA (Act 4 of 2013) requires that processing rest on a lawful basis, that\n-- the data subject be able to establish what is held about them, and that they\n-- can ask for it to be corrected or destroyed. Two things follow that the\n-- schema did not have.\n--\n-- ── consent, with a date ──────────────────────────────────────────────────\n-- \"They accepted the terms\" is not a fact unless it is written down. The\n-- version matters as much as the timestamp: terms change, and consent to one\n-- wording is not consent to a later one, so both are recorded and a change of\n-- version is visible as an absence rather than assumed away.\n\nalter table public.user_profiles\n  add column terms_accepted_at timestamptz,\n  add column terms_version     text,\n  add column privacy_accepted_at timestamptz,\n  add column privacy_version   text;\n\ncomment on column public.user_profiles.terms_accepted_at is\n  'When this person accepted the terms of service. Null means they have not.';\ncomment on column public.user_profiles.terms_version is\n  'Which wording they accepted. Consent to one version is not consent to the next.';\n\n-- An organisation is a separate consenting party: its administrator agrees to\n-- the data processing addendum on the organisation''s behalf, which is a\n-- different act from that person accepting the terms as an individual.\nalter table public.organisations\n  add column dpa_accepted_at timestamptz,\n  add column dpa_version     text,\n  add column dpa_accepted_by uuid references auth.users (id) on delete set null;\n\ncomment on column public.organisations.dpa_accepted_at is\n  'When an administrator accepted the data processing addendum for this organisation.';\n\n-- ── the right to ask ──────────────────────────────────────────────────────\n--\n-- A request is recorded rather than acted on immediately. Export and erasure\n-- both need judgement — an organisation''s records are not one member''s to\n-- delete, and a request from an administrator may implicate colleagues — so\n-- this creates an auditable obligation with a clock on it, which is what the\n-- Act actually asks for.\n\ncreate type public.data_request_kind as enum ('export', 'deletion', 'correction');\ncreate type public.data_request_status as enum ('received', 'in_progress', 'completed', 'refused');\n\ncreate table public.data_requests (\n  id             uuid primary key default gen_random_uuid(),\n  user_id        uuid not null references auth.users (id) on delete cascade,\n  kind           public.data_request_kind not null,\n  status         public.data_request_status not null default 'received',\n  -- What the person said, in their words. Useful for a correction request,\n  -- where the substance is the point.\n  note           text check (note is null or length(note) <= 2000),\n  -- What was done, for the audit trail. Never shown to the requester as-is.\n  resolution     text,\n  requested_at   timestamptz not null default now(),\n  responded_at   timestamptz,\n  created_at     timestamptz not null default now(),\n  updated_at     timestamptz not null default now()\n);\n\ncreate index data_requests_user on public.data_requests (user_id);\ncreate index data_requests_open on public.data_requests (status) where status in ('received', 'in_progress');\n\ncreate trigger data_requests_touch\n  before update on public.data_requests\n  for each row execute function amryn.touch_updated_at();\n\nalter table public.data_requests enable row level security;\nalter table public.data_requests force row level security;\n\n-- A person may see and make their own requests, and nobody else''s. There is\n-- deliberately no policy letting an organisation administrator read these: a\n-- request to exercise a personal right is between the individual and the\n-- responsible party, and an employer reading it would chill the exercise of it.\ncreate policy data_requests_read_own on public.data_requests\n  for select to authenticated\n  using (user_id = auth.uid());\n\ncreate policy data_requests_create_own on public.data_requests\n  for insert to authenticated\n  with check (user_id = auth.uid());\n\n-- No update or delete policy at all. A request cannot be withdrawn by editing\n-- it away, and its status is set by whoever handles it, outside this interface.\n\ngrant select, insert on public.data_requests to authenticated;\n\n-- ── carrying consent through sign-up ──────────────────────────────────────\n--\n-- Consent is given on the sign-up form, but the profile row it belongs on may\n-- not exist yet: where the project confirms addresses by email, the account is\n-- created and the person disappears into their inbox for a while, and where\n-- the trigger below could not be installed the profile is not written until\n-- their first sign-in. Recording the acceptance in the account's own metadata\n-- at the moment it is given, and copying it onto the profile whichever path\n-- creates that profile, is what makes the record survive both gaps.\n--\n-- Both writers use coalesce on the existing timestamp, so a later acceptance\n-- of a newer version is never overwritten by the one captured at sign-up.\n\ncreate or replace function amryn.handle_new_user()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\nbegin\n  insert into public.user_profiles (\n    id, email, full_name, avatar_url,\n    terms_accepted_at, terms_version, privacy_accepted_at, privacy_version\n  )\n  values (\n    new.id,\n    new.email,\n    coalesce(new.raw_user_meta_data ->> 'full_name', new.raw_user_meta_data ->> 'name'),\n    new.raw_user_meta_data ->> 'avatar_url',\n    (new.raw_user_meta_data ->> 'terms_accepted_at')::timestamptz,\n    new.raw_user_meta_data ->> 'terms_version',\n    (new.raw_user_meta_data ->> 'privacy_accepted_at')::timestamptz,\n    new.raw_user_meta_data ->> 'privacy_version'\n  )\n  on conflict (id) do update\n    set email = excluded.email,\n        full_name = coalesce(public.user_profiles.full_name, excluded.full_name),\n        terms_accepted_at = coalesce(public.user_profiles.terms_accepted_at, excluded.terms_accepted_at),\n        terms_version = coalesce(public.user_profiles.terms_version, excluded.terms_version),\n        privacy_accepted_at = coalesce(public.user_profiles.privacy_accepted_at, excluded.privacy_accepted_at),\n        privacy_version = coalesce(public.user_profiles.privacy_version, excluded.privacy_version);\n  return new;\nend;\n$$;\n\ncreate or replace function public.ensure_user_profile()\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  uid uuid := auth.uid();\nbegin\n  if uid is null then\n    return;\n  end if;\n\n  insert into public.user_profiles (\n    id, email, full_name, avatar_url,\n    terms_accepted_at, terms_version, privacy_accepted_at, privacy_version\n  )\n  select\n    u.id,\n    u.email,\n    coalesce(u.raw_user_meta_data ->> 'full_name', u.raw_user_meta_data ->> 'name'),\n    u.raw_user_meta_data ->> 'avatar_url',\n    (u.raw_user_meta_data ->> 'terms_accepted_at')::timestamptz,\n    u.raw_user_meta_data ->> 'terms_version',\n    (u.raw_user_meta_data ->> 'privacy_accepted_at')::timestamptz,\n    u.raw_user_meta_data ->> 'privacy_version'\n  from auth.users u\n  where u.id = uid\n  on conflict (id) do update\n    set email = excluded.email,\n        full_name = coalesce(public.user_profiles.full_name, excluded.full_name),\n        terms_accepted_at = coalesce(public.user_profiles.terms_accepted_at, excluded.terms_accepted_at),\n        terms_version = coalesce(public.user_profiles.terms_version, excluded.terms_version),\n        privacy_accepted_at = coalesce(public.user_profiles.privacy_accepted_at, excluded.privacy_accepted_at),\n        privacy_version = coalesce(public.user_profiles.privacy_version, excluded.privacy_version);\nend;\n$$;\n\nrevoke all on function public.ensure_user_profile() from public, anon;\ngrant execute on function public.ensure_user_profile() to authenticated;\n\nnotify pgrst, 'reload schema';\n\n-- ══════════════════════════════════════════════════════════════════════\n-- 20260831160000_14_security_events.sql\n-- ══════════════════════════════════════════════════════════════════════\ndo $setup$ begin raise notice 'applying 20260831160000_14_security_events.sql'; end $setup$;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- Amryn™ AIGrowthIntelligence® Software\n-- Migration 14 — Security events that can be trusted\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- audit_logs has existed since migration 01 and had one writer: a change of\n-- radar sector scope. Everything a security log exists for — who signed in,\n-- who was invited, who joined, who took a copy of their own information — went\n-- unrecorded, which made the privacy policy's promise that \"sign-ins and\n-- organisation changes are recorded\" a sentence about something that was not\n-- happening.\n--\n-- ── and the writes it did allow were not evidence ─────────────────────────\n-- The insert policy was:\n--\n--   with check (organisation_id is null or amryn.is_member(organisation_id))\n--\n-- Any member could write any row: an action of their choosing, a summary of\n-- their choosing, and — because actor_id was supplied by the caller — somebody\n-- else's name on it. A log a subject can forge is not an audit log; it is a\n-- table with an official-sounding name, and relying on it in an investigation\n-- would be worse than having none.\n--\n-- So the row is written by a function that decides the two fields that matter,\n-- and the direct insert is withdrawn.\n\ncreate or replace function public.record_security_event(\n  p_organisation_id uuid,\n  p_action          text,\n  p_entity_type     text default 'account',\n  p_entity_id       text default null,\n  p_summary         text default null,\n  p_metadata        jsonb default '{}'::jsonb\n)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  uid uuid := auth.uid();\nbegin\n  -- The actor is never taken from the caller. This is the whole point.\n  if p_organisation_id is not null and not amryn.is_member(p_organisation_id) then\n    raise exception 'not a member of that organisation' using errcode = '42501';\n  end if;\n\n  insert into public.audit_logs (\n    organisation_id, actor_id, action, entity_type, entity_id, summary, metadata\n  )\n  values (\n    p_organisation_id, uid, p_action, coalesce(p_entity_type, 'account'),\n    p_entity_id, p_summary, coalesce(p_metadata, '{}'::jsonb)\n  );\nend;\n$$;\n\ncomment on function public.record_security_event is\n  'The only way the application writes an audit row. Sets actor_id from the session, so an entry cannot be attributed to somebody else.';\n\nrevoke all on function public.record_security_event(uuid, text, text, text, text, jsonb)\n  from public, anon;\ngrant execute on function public.record_security_event(uuid, text, text, text, text, jsonb)\n  to authenticated;\n\n-- A sign-in has no organisation yet, and the person may belong to none. That\n-- row is ours as responsible party rather than any employer's, which is also\n-- why the read policy below leaves it invisible to organisation administrators.\ncreate or replace function public.record_account_event(\n  p_action  text,\n  p_summary text default null\n)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\nbegin\n  insert into public.audit_logs (organisation_id, actor_id, action, entity_type, summary)\n  values (null, auth.uid(), p_action, 'account', p_summary);\nend;\n$$;\n\nrevoke all on function public.record_account_event(text, text) from public, anon;\n-- anon may call this one: a failed sign-in has no session, and a log that\n-- records only the attempts that succeeded is not a security log. The function\n-- writes auth.uid(), which is null in that case, so an anonymous caller cannot\n-- attribute an entry to anybody.\ngrant execute on function public.record_account_event(text, text) to authenticated, anon;\n\n-- ── withdraw the forgeable path ──────────────────────────────────────────\n--\n-- Two changes, and the second is the one that makes the first survivable.\n--\n-- Dropping the policy is what removes the forgeable write. But audit_logs\n-- carries FORCE row level security, which applies to the table's owner too —\n-- and with no insert policy left, \"everyone\" includes the owner. Every\n-- SECURITY DEFINER function that writes an audit row runs as that owner:\n-- the two below, and create_organisation(), whose last statement records\n-- 'organisation.created'. An error inside a function rolls the whole call\n-- back, so dropping the policy alone would have broken organisation creation\n-- outright — on the onboarding form, for every new customer.\n--\n-- On a local PostgreSQL this is invisible: there the owner is a superuser, and\n-- a superuser bypasses row level security whether or not it is forced. On a\n-- hosted Supabase project the postgres role is not a superuser, so it is\n-- subject to the policies like anyone else. This is the third time that\n-- difference has hidden a fault from the test suite; supabase/tests/17 now\n-- reproduces it deliberately.\n--\n-- Lifting FORCE is the correct answer rather than a workaround. What must be\n-- true of an append-only log is that the application cannot write to it\n-- directly and can only read its own organisation's rows — and both survive:\n-- the revoke below removes the write privilege from authenticated entirely,\n-- which is a stronger guarantee than a policy, and audit_read still governs\n-- every read, because a caller is never the owner. The only writers left are\n-- the definer functions, which is what \"the only way the application writes an\n-- audit row\" was meant to mean.\nalter table public.audit_logs no force row level security;\n\ndrop policy if exists audit_append on public.audit_logs;\nrevoke insert, update, delete on public.audit_logs from authenticated, anon;\n\n-- Reading is unchanged and deliberately narrow: an organisation administrator\n-- with view_audit_log sees their own organisation's entries. Account-level\n-- rows carry no organisation_id and so match no policy at all — nobody reads\n-- those through the API, which is correct for a record of an individual's\n-- sign-ins held by us rather than by their employer.\n\nnotify pgrst, 'reload schema';\n\n-- ══════════════════════════════════════════════════════════════════════\n-- 20260831180000_15_two_factor.sql\n-- ══════════════════════════════════════════════════════════════════════\ndo $setup$ begin raise notice 'applying 20260831180000_15_two_factor.sql'; end $setup$;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- Amryn™ AIGrowthIntelligence® Software\n-- Migration 15 — Two-factor authentication\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- Until now a stolen password was the whole attack. For a platform holding a\n-- company's financial records, customer list and pipeline, that is the largest\n-- single gap in the product.\n--\n-- Supabase issues and verifies the second factor itself, so none of the TOTP\n-- machinery lives here. What lives here is the part an application must not\n-- get wrong: making the requirement real.\n--\n-- ── why this is not only an application check ─────────────────────────────\n-- The obvious implementation is a redirect: if the session has not completed\n-- the challenge, send it to the verify page. That is worth doing and is not\n-- enough. Every browser session also carries a key that speaks to PostgREST\n-- directly, and a session that skipped the challenge is a perfectly valid\n-- session as far as the database is concerned — so anyone willing to use the\n-- API instead of the interface would read everything the redirect was hiding.\n-- A second factor that can be walked around with curl is a checkbox, not a\n-- control.\n--\n-- So the requirement is enforced where the data is. Supabase records the\n-- authenticator assurance level in the token as `aal`: aal1 is a password,\n-- aal2 is a password and a second factor. Every policy in this schema already\n-- reaches the caller through amryn.is_member() or amryn.has_permission(), so\n-- adding the condition to those two puts it in front of all 147 of them.\n\n-- ── who has it turned on ──────────────────────────────────────────────────\n--\n-- Kept here rather than read from auth.mfa_factors, which belongs to another\n-- role and may not be readable from this schema on every project. A guard that\n-- cannot read its own input has to choose between failing open — which is not\n-- a guard — and locking every customer out of their data over a missing grant.\n-- This is our own table, and the application writes it in the same action that\n-- verifies the factor.\nalter table public.user_profiles\n  add column mfa_enabled boolean not null default false,\n  add column mfa_enabled_at timestamptz;\n\ncomment on column public.user_profiles.mfa_enabled is\n  'Whether this person has a verified second factor. Set when enrolment is confirmed, cleared when the last factor is removed. The database refuses their data to a session that has not presented it.';\n\n-- ── the guard ─────────────────────────────────────────────────────────────\ncreate or replace function amryn.mfa_satisfied()\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = public, pg_temp\nas $$\n  select\n    -- Presented the second factor on this session.\n    coalesce(auth.jwt() ->> 'aal', 'aal1') = 'aal2'\n    -- Or has none to present. Someone who has not turned it on is not asked\n    -- for it, and neither is a background job, which carries no token at all:\n    -- auth.uid() is null there, the row is not found, and the answer is true.\n    or not exists (\n      select 1\n      from public.user_profiles p\n      where p.id = auth.uid()\n        and p.mfa_enabled\n    );\n$$;\n\ncomment on function amryn.mfa_satisfied is\n  'False only for a session belonging to someone with two-factor turned on that has not completed the second step. Used by is_member() and has_permission(), so it applies to every policy without repeating it in each.';\n\n-- ── applied to the two functions every policy goes through ────────────────\n--\n-- Deliberately not added to the policies one at a time. There are 147 of them;\n-- a condition repeated 147 times is a condition that will be missing from the\n-- 148th.\n\ncreate or replace function amryn.is_member(p_org uuid)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = public, pg_temp\nas $$\n  select amryn.mfa_satisfied() and exists (\n    select 1\n    from public.organisation_members m\n    where m.organisation_id = p_org\n      and m.user_id = auth.uid()\n      and m.status = 'active'\n  );\n$$;\n\ncreate or replace function amryn.has_permission(p_org uuid, p_permission text)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = public, pg_temp\nas $$\n  with member as (\n    select m.id, m.role\n    from public.organisation_members m\n    where m.organisation_id = p_org\n      and m.user_id = auth.uid()\n      and m.status = 'active'\n    limit 1\n  ),\n  override as (\n    select o.granted\n    from public.member_permission_overrides o\n    join member on member.id = o.member_id\n    where o.permission_key = p_permission\n    limit 1\n  ),\n  role_default as (\n    select true as granted\n    from public.role_permissions rp\n    join member on member.role = rp.role\n    where rp.permission_key = p_permission\n    limit 1\n  )\n  select amryn.mfa_satisfied() and coalesce(\n    (select granted from override),\n    (select granted from role_default),\n    false\n  );\n$$;\n\n-- member_role() is deliberately left alone. It answers \"what is this person's\n-- role\", which the interface needs in order to render the page that explains\n-- they must complete the second step — and it returns a label, never data.\n\n-- ── recovery codes ────────────────────────────────────────────────────────\n--\n-- The failure mode of two-factor authentication is not an attacker; it is a\n-- lost phone. Without a way back, turning it on is a way to lose an account,\n-- and the people most likely to turn it on are the ones with the most to lose.\n--\n-- Ten single-use codes, stored as SHA-256 hashes for the same reason passwords\n-- are: a database that can produce the codes is a database that can bypass the\n-- factor. Redeeming one is not a sign-in — it removes the factor, and the\n-- person is asked to enrol again. So the two things needed to get back in are\n-- the password and a code, which is still two factors.\n\ncreate table public.mfa_recovery_codes (\n  id         uuid primary key default gen_random_uuid(),\n  user_id    uuid not null references auth.users (id) on delete cascade,\n  code_hash  text not null,\n  used_at    timestamptz,\n  created_at timestamptz not null default now(),\n  unique (user_id, code_hash)\n);\n\ncreate index mfa_recovery_codes_user on public.mfa_recovery_codes (user_id)\n  where used_at is null;\n\nalter table public.mfa_recovery_codes enable row level security;\n\n-- No force: the definer functions below are the only writers, exactly as with\n-- audit_logs. See migration 14 for why forcing it would refuse them too.\n\n-- A person may see that they have codes, and how many are left. The hash is\n-- readable in the sense that any column of a visible row is, which is why it\n-- is a hash: reading it yields nothing usable. Nobody sees anybody else's.\ncreate policy mfa_recovery_read_own on public.mfa_recovery_codes\n  for select to authenticated\n  using (user_id = auth.uid());\n\n-- No insert, update or delete policy at all. Codes are issued and spent by the\n-- functions below, so a caller cannot mint themselves a code, and cannot\n-- un-spend one.\ngrant select on public.mfa_recovery_codes to authenticated;\nrevoke insert, update, delete on public.mfa_recovery_codes from authenticated, anon;\n\n/**\n * Replaces this person's recovery codes with the ones given.\n *\n * Takes hashes, never codes: the plaintext is generated in the application,\n * shown once, and never sent to the database. Replacing rather than adding,\n * because a fresh set has to invalidate the old one — otherwise a code from a\n * printout two years ago still works.\n */\ncreate or replace function public.replace_recovery_codes(p_hashes text[])\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  uid uuid := auth.uid();\nbegin\n  if uid is null then\n    raise exception 'authentication required' using errcode = '42501';\n  end if;\n\n  if array_length(p_hashes, 1) is null or array_length(p_hashes, 1) > 20 then\n    raise exception 'expected between 1 and 20 recovery codes' using errcode = '22023';\n  end if;\n\n  delete from public.mfa_recovery_codes where user_id = uid;\n\n  insert into public.mfa_recovery_codes (user_id, code_hash)\n  select uid, hash from unnest(p_hashes) as hash;\nend;\n$$;\n\nrevoke all on function public.replace_recovery_codes(text[]) from public, anon;\ngrant execute on function public.replace_recovery_codes(text[]) to authenticated;\n\n/**\n * Spends a recovery code, if it is one of this person's unused ones.\n *\n * Returns whether it was accepted. The update is the check — a single\n * statement that matches only an unused code and marks it used in the same\n * breath, so two simultaneous attempts with the same code cannot both succeed.\n */\ncreate or replace function public.redeem_recovery_code(p_hash text)\nreturns boolean\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  uid     uuid := auth.uid();\n  spent   uuid;\nbegin\n  if uid is null then\n    raise exception 'authentication required' using errcode = '42501';\n  end if;\n\n  update public.mfa_recovery_codes\n     set used_at = now()\n   where user_id = uid\n     and code_hash = p_hash\n     and used_at is null\n  returning id into spent;\n\n  if spent is null then\n    return false;\n  end if;\n\n  -- The code is spent and the factor is about to be removed by the caller,\n  -- which holds the credentials to do it. Clearing the flag here keeps the\n  -- two in step: a profile that still said mfa_enabled with no factor left\n  -- would lock the account out of its own data with nothing able to satisfy\n  -- the guard.\n  update public.user_profiles\n     set mfa_enabled = false, mfa_enabled_at = null\n   where id = uid;\n\n  return true;\nend;\n$$;\n\nrevoke all on function public.redeem_recovery_code(text) from public, anon;\ngrant execute on function public.redeem_recovery_code(text) to authenticated;\n\nnotify pgrst, 'reload schema';\n\n-- ══════════════════════════════════════════════════════════════════════\n-- 20260901090000_16_subscription_entitlements.sql\n-- ══════════════════════════════════════════════════════════════════════\ndo $setup$ begin raise notice 'applying 20260901090000_16_subscription_entitlements.sql'; end $setup$;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- Amryn™ AIGrowthIntelligence® Software\n-- Migration 16 — Subscription plans, entitlements and lapsed-account writes\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- Migration 01 gave every organisation a `subscriptions` row carrying a plan\n-- name and three numbers. Nothing read the plan. What a tier actually included\n-- lived in a constant array on the billing page, and what a tier permitted\n-- lived nowhere at all — an organisation whose subscription was cancelled a\n-- year ago kept full use of the platform, because no code ever asked.\n--\n-- This migration supplies the two halves that were missing:\n--\n--   1. A catalogue. What each tier costs and what it includes are rows, so the\n--      pricing page, the entitlement check and the payment webhook read one\n--      answer. Changing what Growth includes is an update, not a deployment.\n--\n--   2. Enforcement. A subscription that has lapsed stops write access to the\n--      business data, in the database, for every caller — including one\n--      holding a valid token and talking to PostgREST directly rather than to\n--      our pages.\n--\n-- ── why writes and not reads ──────────────────────────────────────────────\n-- The blunt version of this is to refuse a lapsed organisation everything.\n-- That is wrong on two counts. Commercially, a customer who cannot see the\n-- invoice cannot pay it. Legally, POPIA s23 gives the data subject a right of\n-- access that does not lapse when a card expires — locking someone out of\n-- their own records to collect a debt would be the platform withholding\n-- personal information it holds on request.\n--\n-- So a lapsed organisation keeps reading its own data, keeps its billing page,\n-- keeps its export and deletion requests — and cannot add to, change or\n-- destroy the business records until the subscription is current again.\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- 1. The catalogue\n-- ═══════════════════════════════════════════════════════════════════════════\n\ncreate table public.subscription_plans (\n  plan                 public.subscription_plan primary key,\n  name                 text    not null,\n  tagline              text    not null,\n  -- Rand, in cents. Null where the price is negotiated rather than published.\n  price_cents_monthly  integer check (price_cents_monthly is null or price_cents_monthly >= 0),\n  price_cents_annual   integer check (price_cents_annual is null or price_cents_annual >= 0),\n  currency_code        char(3) not null default 'ZAR',\n  -- The defaults a new subscription on this tier is opened with. The\n  -- subscription row remains the effective state: an Enterprise contract is\n  -- negotiated, and negotiating it must not require a catalogue edit that\n  -- would move every other Enterprise customer with it.\n  seats                integer not null default 3  check (seats > 0),\n  -- Null is no limit. It has to be nullable for the same reason `included`\n  -- and `limit_value` are separate columns below: unlimited and not-sold are\n  -- different answers, and one number cannot carry both.\n  data_source_limit    integer check (data_source_limit is null or data_source_limit >= 0),\n  ai_credits_monthly   integer not null default 500 check (ai_credits_monthly >= 0),\n  trial_days           integer not null default 30 check (trial_days >= 0),\n  -- Enterprise is a conversation, not a checkout button.\n  contact_sales        boolean not null default false,\n  is_public            boolean not null default true,\n  sort_order           integer not null default 0,\n  created_at           timestamptz not null default now(),\n  updated_at           timestamptz not null default now()\n);\n\ncomment on table public.subscription_plans is\n  'What each tier costs and what a subscription on it is opened with. Read by the pricing page, the billing page and the payment webhook, so the three cannot disagree.';\n\ncreate trigger subscription_plans_touch\n  before update on public.subscription_plans\n  for each row execute function amryn.touch_updated_at();\n\ninsert into public.subscription_plans\n  (plan, name, tagline, price_cents_monthly, price_cents_annual, seats, data_source_limit, ai_credits_monthly, trial_days, contact_sales, sort_order)\nvalues\n  ('starter',      'Starter',      'One site, two data sources, the numbers that matter.',\n     99900,  1_078_900,   3,   2,    500, 30, false, 1),\n  ('growth',       'Growth',       'Several branches, eight sources, and the market watched for you.',\n    399900,  4_318_900,  10,   8,  2_500, 30, false, 2),\n  ('professional', 'Professional', 'The full radar, unlimited sources, reports on your own terms.',\n    999900, 10_798_900,  30, null, 10_000, 14, false, 3),\n  ('enterprise',   'Enterprise',   'Single sign-on, negotiated scale and a named person to call.',\n   2_000_000, null,     100, null, 50_000,  0, true,  4);\n\ncomment on column public.subscription_plans.price_cents_annual is\n  'Twelve months for the price of about eleven. Null where the tier is negotiated.';\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- 2. Entitlements\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- Deliberately the same shape as `permissions`: a catalogue of keys and a\n-- join table saying which tier carries which. The application mirrors the\n-- vocabulary so it can explain a refusal, and the database decides.\n--\n-- Permissions and entitlements answer different questions and are not\n-- interchangeable. A permission asks \"is this person allowed to?\" — an analyst\n-- may not change billing however much the company pays. An entitlement asks\n-- \"has this company bought it?\" — the founder on Starter is allowed to use the\n-- competitor radar and has not purchased it. Both must be satisfied.\n\ncreate table public.entitlements (\n  key         text primary key,\n  category    text not null,\n  name        text not null,\n  description text not null,\n  -- 'feature' is on or off. 'quota' carries a number, and null means no limit.\n  kind        text not null default 'feature' check (kind in ('feature', 'quota')),\n  sort_order  integer not null default 0\n);\n\ncomment on table public.entitlements is\n  'The vocabulary of what a subscription can include. Mirrored in src/lib/billing/entitlements.ts so the application can name what is missing.';\n\ninsert into public.entitlements (key, category, name, description, kind, sort_order) values\n  ('command_centre',        'Intelligence', 'Executive Command Centre',   'The daily view of the business.',                            'feature',  1),\n  ('financial_intelligence','Intelligence', 'Financial intelligence',     'Revenue, margin, cash and the forecast.',                    'feature',  2),\n  ('performance_tracking',  'Intelligence', 'Performance tracking',       'KPIs, goals and the action centre.',                         'feature',  3),\n  ('risk_radar',            'Intelligence', 'Risk radar',                 'Risks scored, ranked and tracked to closure.',               'feature',  4),\n  ('opportunity_pipeline',  'Growth',       'Opportunity pipeline',       'Opportunities found, scored and assigned.',                  'feature',  5),\n  ('market_intelligence',   'Growth',       'Market intelligence',        'Signals from your market, read for you.',                    'feature',  6),\n  ('competitor_radar',      'Growth',       'Competitor radar',           'Named competitors watched continuously.',                    'feature',  7),\n  ('ai_assistant',          'Intelligence', 'AI DigitalTwin® assistant',  'Ask the twin about your own figures.',                       'feature',  8),\n  ('report_weekly',         'Reporting',    'Weekly briefing',            'The weekly brief, written and delivered.',                   'feature',  9),\n  ('report_monthly',        'Reporting',    'Monthly board pack',         'The monthly review, in board-meeting form.',                 'feature', 10),\n  ('custom_reports',        'Reporting',    'Reports on your own terms',  'Choose the sections, the period and the recipients.',        'feature', 11),\n  ('api_access',            'Operations',   'API access',                 'Read your intelligence from your own systems.',              'feature', 12),\n  ('sso',                   'Operations',   'Single sign-on',             'Sign in with your company identity provider.',               'feature', 13),\n  ('white_label',           'Operations',   'Your branding',              'Reports and the interface in your own colours.',             'feature', 14),\n  ('priority_support',      'Support',      'Priority support',           'A four-hour response during business hours.',                'feature', 15),\n  ('success_manager',       'Support',      'Named success manager',      'A person who knows your business and answers the phone.',    'feature', 16),\n  ('seats',                 'Operations',   'People',                     'How many colleagues can be given an account.',               'quota',   17),\n  ('data_sources',          'Operations',   'Data sources',               'How many systems can feed the platform.',                    'quota',   18),\n  ('ai_credits',            'Intelligence', 'AI usage',                   'How much the assistant may be asked each month.',            'quota',   19),\n  ('audit_retention_days',  'Operations',   'Audit history',              'How far back the audit log is kept.',                        'quota',   20),\n  ('branches',              'Operations',   'Sites',                      'How many branches may be tracked separately.',               'quota',   21);\n\ncreate table public.plan_entitlements (\n  plan            public.subscription_plan not null references public.subscription_plans (plan) on delete cascade,\n  entitlement_key text not null references public.entitlements (key) on delete cascade,\n  included        boolean not null default true,\n  -- Only meaningful for a quota. Null on an included quota means no limit.\n  limit_value     integer check (limit_value is null or limit_value >= 0),\n  primary key (plan, entitlement_key)\n);\n\ncomment on table public.plan_entitlements is\n  'The matrix. One row per tier per entitlement; absent is the same as not included, so a new entitlement is off everywhere until it is deliberately sold.';\n\n-- Features. Written as a matrix rather than four separate inserts so that the\n-- shape of the offer is legible in one screen — which is the point of having\n-- it in one place at all.\ninsert into public.plan_entitlements (plan, entitlement_key, included)\nselect t.plan, m.key, t.included\nfrom (values\n  --  key                       starter growth  professional enterprise\n  ('command_centre',            true,   true,   true,        true),\n  ('financial_intelligence',    true,   true,   true,        true),\n  ('performance_tracking',      true,   true,   true,        true),\n  ('risk_radar',                false,  true,   true,        true),\n  ('opportunity_pipeline',      false,  true,   true,        true),\n  ('market_intelligence',       false,  true,   true,        true),\n  ('competitor_radar',          false,  false,  true,        true),\n  ('ai_assistant',              true,   true,   true,        true),\n  ('report_weekly',             true,   true,   true,        true),\n  ('report_monthly',            false,  true,   true,        true),\n  ('custom_reports',            false,  false,  true,        true),\n  ('api_access',                false,  false,  true,        true),\n  ('sso',                       false,  false,  false,       true),\n  ('white_label',               false,  false,  false,       true),\n  ('priority_support',          false,  false,  true,        true),\n  ('success_manager',           false,  false,  false,       true)\n) as m(key, starter, growth, professional, enterprise)\ncross join lateral (values\n  ('starter'::public.subscription_plan,      m.starter),\n  ('growth'::public.subscription_plan,       m.growth),\n  ('professional'::public.subscription_plan, m.professional),\n  ('enterprise'::public.subscription_plan,   m.enterprise)\n) as t(plan, included);\n\n-- Quotas.\n--\n-- The three that a subscription carries a column for are selected *from* the\n-- catalogue rather than typed again beside it. Written out by hand they were\n-- wrong within the hour: the matrix said Professional had unlimited data\n-- sources while the catalogue said a hundred, and both were being read — the\n-- pricing page from one, the enforcement from the other. Two places to state\n-- one number is one place too many.\ninsert into public.plan_entitlements (plan, entitlement_key, included, limit_value)\nselect plan, 'seats',        true, seats              from public.subscription_plans\nunion all\nselect plan, 'data_sources', true, data_source_limit  from public.subscription_plans\nunion all\nselect plan, 'ai_credits',   true, ai_credits_monthly from public.subscription_plans;\n\n-- The rest have no column on `subscriptions` and live here alone.\ninsert into public.plan_entitlements (plan, entitlement_key, included, limit_value) values\n  ('starter',      'audit_retention_days', true,    90),\n  ('growth',       'audit_retention_days', true,   365),\n  ('professional', 'audit_retention_days', true, 1_095),\n  ('enterprise',   'audit_retention_days', true,  null),\n\n  ('starter',      'branches',             true,     1),\n  ('growth',       'branches',             true,    10),\n  ('professional', 'branches',             true,  null),\n  ('enterprise',   'branches',             true,  null);\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- 3. What the subscription now has to record\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- There is no payment gateway. Customers pay by electronic transfer against a\n-- reference, email the proof, and an operator issues an activation link. That\n-- is a deliberate choice and not a placeholder: it needs no card processing\n-- agreement, no gateway account, no secret in the deployment, and it matches\n-- how South African business-to-business software of this size is actually\n-- bought. The columns below record the outcome of that process, whoever\n-- eventually performs it — a gateway added later writes the same fields.\n\n-- Null is no limit, matching the catalogue. It was not null with a default of\n-- two, which left no way to express the unlimited sources Professional is sold\n-- with other than a large number that would eventually be reached.\nalter table public.subscriptions\n  alter column data_source_limit drop not null;\n\nalter table public.subscriptions\n  add column cancel_at_period_end boolean not null default false,\n  add column cancelled_at         timestamptz,\n  -- A payment that has not landed yet is not the same as a refusal to pay.\n  -- Transfers between South African banks still take a day, and a customer who\n  -- has paid should not lose the platform while the money is in flight. Set\n  -- when the period lapses; cleared when an activation is redeemed.\n  add column grace_until          timestamptz,\n  add column last_payment_at      timestamptz,\n  add column activated_at         timestamptz,\n  add column activated_by         uuid references auth.users (id) on delete set null;\n\ncomment on column public.subscriptions.grace_until is\n  'How long an unpaid period is tolerated before writes are refused. Null when the subscription is not in arrears.';\n\n-- Bring the existing rows in line with the catalogue they were opened against.\n-- Every organisation created before this migration is on Starter's defaults\n-- already; this makes that a fact rather than a coincidence of two numbers\n-- that happened to be typed the same.\nupdate public.subscriptions s\n   set price_cents_monthly = coalesce(p.price_cents_monthly, s.price_cents_monthly)\n  from public.subscription_plans p\n where p.plan = s.plan\n   and s.price_cents_monthly is distinct from coalesce(p.price_cents_monthly, s.price_cents_monthly);\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- 4. Paying by transfer, and being activated\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- The sequence, and where each step is recorded:\n--\n--   1. The customer chooses a plan and a term.       request_subscription()\n--      They are given a reference to quote on the transfer.\n--   2. They pay, and email the proof.                (outside the platform)\n--   3. An operator confirms the money arrived.       issue_activation()\n--      That mints a one-time link and returns it to be sent to the customer.\n--   4. The customer opens the link.                  redeem_activation()\n--      The plan is applied and the period starts from that moment.\n--\n-- Step 3 is the control. Nothing a customer can do — not the request, not the\n-- proof they attach, not any field they can write — moves a subscription to\n-- active. The platform never takes the customer's word for a payment, which is\n-- the same rule a gateway integration would follow when it refuses to trust\n-- the browser and waits for the webhook.\n\ncreate table public.subscription_activations (\n  id              uuid primary key default gen_random_uuid(),\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  plan            public.subscription_plan not null,\n  -- One month or twelve. Stored rather than derived so a change to the\n  -- catalogue's annual price cannot retrospectively alter what was invoiced.\n  term_months     integer not null default 1 check (term_months in (1, 12)),\n  amount_cents    integer not null check (amount_cents >= 0),\n  currency_code   char(3) not null default 'ZAR',\n  -- What the customer quotes on the transfer, and what the operator matches\n  -- the proof against. Unique, and generated rather than chosen.\n  reference       text not null unique,\n\n  state           text not null default 'awaiting_payment'\n                    check (state in ('awaiting_payment', 'payment_confirmed', 'activated', 'cancelled', 'expired')),\n\n  requested_by    uuid references auth.users (id) on delete set null,\n  requested_at    timestamptz not null default now(),\n\n  -- Set at step 3. Never the link itself: only a SHA-256 hash is stored, so a\n  -- leaked backup activates nothing. The raw token exists once, in the\n  -- response to the operator who will send it on. Same rule as invitations.\n  token_hash      text unique,\n  confirmed_by    uuid references auth.users (id) on delete set null,\n  confirmed_at    timestamptz,\n  payment_note    text,\n  expires_at      timestamptz,\n\n  activated_at    timestamptz,\n  activated_by    uuid references auth.users (id) on delete set null,\n\n  created_at      timestamptz not null default now(),\n  updated_at      timestamptz not null default now(),\n\n  -- The states are not independent of the columns that record them.\n  constraint confirmed_carries_a_token check (\n    state = 'awaiting_payment' or state = 'cancelled' or token_hash is not null\n  ),\n  constraint activated_carries_a_time check (\n    (state = 'activated') = (activated_at is not null)\n  )\n);\n\ncomment on table public.subscription_activations is\n  'One row per attempt to buy or renew a subscription: what was asked for, what reference was quoted, who confirmed the money arrived, and when the customer redeemed the link. The billing history a dispute is answered from.';\n\n-- One open request per organisation. A partial index rather than a plain\n-- constraint, so the same organisation can request again after cancelling,\n-- letting a request expire, or completing one.\ncreate unique index subscription_activations_open\n  on public.subscription_activations (organisation_id)\n  where state in ('awaiting_payment', 'payment_confirmed');\n\ncreate index subscription_activations_org_idx\n  on public.subscription_activations (organisation_id, requested_at desc);\n\ncreate trigger subscription_activations_touch\n  before update on public.subscription_activations\n  for each row execute function amryn.touch_updated_at();\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- 5. Reading an entitlement\n-- ═══════════════════════════════════════════════════════════════════════════\n\n-- Is this organisation's subscription in a state that permits work?\n--\n-- Split out from the entitlement question because the two fail differently: a\n-- missing entitlement is an upgrade, an inactive subscription is a payment.\ncreate or replace function amryn.subscription_current(org uuid)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = public, pg_temp\nas $$\n  select coalesce(\n    (select\n       case s.status\n         when 'active'    then true\n         -- A trial is a subscription until the day it says it is not.\n         when 'trialing'  then coalesce(s.trial_ends_at, s.current_period_end) > now()\n         -- In arrears, inside the grace period we allowed for it.\n         when 'past_due'  then coalesce(s.grace_until, s.current_period_end + interval '7 days') > now()\n         when 'cancelled' then false\n         else false\n       end\n     from public.subscriptions s\n     where s.organisation_id = org),\n    -- No subscription row is not a free pass. Every organisation is created\n    -- with one; an organisation without one is a broken record, and the safe\n    -- reading of a broken billing record is \"not paid\".\n    false);\n$$;\n\ncomment on function amryn.subscription_current is\n  'Whether the organisation may currently be worked in. Reads are never gated on this — see the header of migration 16.';\n\n-- Does the organisation''s plan include this?\n--\n-- Note what is *not* here: the subscription''s status. A cancelled Professional\n-- customer still has the Professional feature set — they simply cannot write.\n-- Conflating the two would mean a lapsed account silently losing pages as well\n-- as write access, and being told the wrong thing about why.\ncreate or replace function amryn.has_entitlement(org uuid, key text)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = public, pg_temp\nas $$\n  select coalesce(\n    (select pe.included\n       from public.subscriptions s\n       join public.plan_entitlements pe\n         on pe.plan = s.plan and pe.entitlement_key = key\n      where s.organisation_id = org),\n    false);\n$$;\n\n-- The number attached to a quota, or null for no limit.\n--\n-- The subscription row wins over the catalogue where it carries its own\n-- column, because that is where a negotiated contract is recorded. The\n-- catalogue is what a tier opens with, not a ceiling it can never exceed.\ncreate or replace function amryn.entitlement_limit(org uuid, key text)\nreturns integer\nlanguage sql\nstable\nsecurity definer\nset search_path = public, pg_temp\nas $$\n  select case key\n    when 'seats'        then s.seats\n    when 'data_sources' then s.data_source_limit\n    when 'ai_credits'   then s.ai_credits_monthly\n    else pe.limit_value\n  end\n  from public.subscriptions s\n  left join public.plan_entitlements pe\n    on pe.plan = s.plan and pe.entitlement_key = key\n  where s.organisation_id = org;\n$$;\n\n-- One round trip for the whole picture, which is what a page render needs.\ncreate view public.organisation_entitlements\nwith (security_invoker = true) as\nselect\n  s.organisation_id,\n  e.key            as entitlement_key,\n  e.category,\n  e.name,\n  e.description,\n  e.kind,\n  e.sort_order,\n  coalesce(pe.included, false) as included,\n  case e.key\n    when 'seats'        then s.seats\n    when 'data_sources' then s.data_source_limit\n    when 'ai_credits'   then s.ai_credits_monthly\n    else pe.limit_value\n  end              as limit_value\nfrom public.subscriptions s\ncross join public.entitlements e\nleft join public.plan_entitlements pe\n  on pe.plan = s.plan and pe.entitlement_key = e.key;\n\ncomment on view public.organisation_entitlements is\n  'Every entitlement resolved for every organisation the caller can see. security_invoker, so Row Level Security on subscriptions decides which organisations that is.';\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- 6. Refusing writes on a lapsed subscription\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- ── why a trigger and not a policy ────────────────────────────────────────\n-- The policy version of this means appending a condition to the `with check`\n-- of every write policy in the schema — around ninety of them, each edited by\n-- hand, with no way to assert afterwards that none was missed. Worse, the\n-- obvious shortcut of folding the condition into amryn.has_permission() would\n-- catch reads too: several select policies are written against a manage_\n-- permission, so a lapsed customer would lose sight of their own invoices,\n-- which is the one thing they must be able to see.\n--\n-- A trigger separates the two cleanly. It fires on writes and never on reads,\n-- it attaches by iterating the catalogue rather than by being remembered, and\n-- it is one function to read when someone asks what the rule is.\n\ncreate or replace function amryn.refuse_lapsed_write()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  org uuid;\nbegin\n  -- The service role and the owner carry no `sub` claim: a webhook applying a\n  -- payment, a scheduled job and a migration must all keep working, and it is\n  -- specifically a payment that has to get through to end the lapse.\n  if coalesce(nullif(current_setting('request.jwt.claim.sub', true), ''),\n              nullif(auth.jwt() ->> 'sub', '')) is null then\n    return coalesce(new, old);\n  end if;\n\n  org := case tg_op when 'DELETE' then old.organisation_id else new.organisation_id end;\n  if org is null then\n    return coalesce(new, old);\n  end if;\n\n  if not amryn.subscription_current(org) then\n    raise exception\n      'This organisation''s subscription is not active, so its records cannot be changed. Reading, exporting and billing are unaffected.'\n      using errcode = 'check_violation',\n            hint = 'Settle the subscription on the billing page to resume.';\n  end if;\n\n  return coalesce(new, old);\nend $$;\n\ncomment on function amryn.refuse_lapsed_write is\n  'Refuses changes to business records while a subscription is lapsed. Reads, billing and data-rights records are exempt — see migration 16 header.';\n\n-- Which tables it guards.\n--\n-- Everything owned by an organisation, except:\n--   billing              a customer who cannot pay cannot recover, and the\n--                        activation that ends the lapse is itself a write\n--   audit                the record of what happened must not have a gap\n--   membership           removing a person's access must always be possible\n--\n-- The POPIA machinery is absent from the list for a better reason than\n-- exemption: none of it is organisation-scoped. A data request belongs to the\n-- person who made it and consent is columns on user_profiles and\n-- organisations, so the loop below — which selects on organisation_id — never\n-- reaches any of them. The right of access keeps working for the same reason\n-- reads do, not because somebody remembered to name it here.\ndo $$\ndeclare\n  t text;\n  exempt constant text[] := array[\n    'subscriptions', 'billing_records', 'subscription_activations',\n    'audit_logs',\n    'organisation_members', 'member_permission_overrides',\n    'organisation_invitations'\n  ];\nbegin\n  for t in\n    select c.relname\n      from pg_class c\n      join pg_namespace n on n.oid = c.relnamespace\n      join pg_attribute a on a.attrelid = c.oid and a.attname = 'organisation_id'\n     where n.nspname = 'public'\n       and c.relkind = 'r'\n       and not a.attisdropped\n       and c.relname <> all (exempt)\n     order by c.relname\n  loop\n    execute format(\n      'create trigger %I before insert or update or delete on public.%I '\n      || 'for each row execute function amryn.refuse_lapsed_write()',\n      left('zz_subscription_' || t, 63), t);\n  end loop;\nend $$;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- 7. Moving a subscription, from one place\n-- ═══════════════════════════════════════════════════════════════════════════\n\n-- Puts an organisation on a plan and copies the catalogue's opening figures.\n--\n-- Definer, and deliberately not callable by a signed-in user. This is the only\n-- statement in the schema that makes a subscription active, so it is reached\n-- through redeem_activation() or by an operator holding the service role, and\n-- never by posting to an endpoint.\ncreate or replace function public.apply_subscription_plan(\n  p_organisation uuid,\n  p_plan         public.subscription_plan,\n  p_status       public.subscription_status default null,\n  p_period_start timestamptz default null,\n  p_period_end   timestamptz default null\n)\nreturns public.subscriptions\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  catalogue public.subscription_plans;\n  updated     public.subscriptions;\n  -- Not named `status`: PL/pgSQL refuses a bare name that matches both a\n  -- variable and a column of a table in the statement, and `subscriptions`\n  -- has one.\n  next_status public.subscription_status;\nbegin\n  select * into catalogue from public.subscription_plans where plan = p_plan;\n  if not found then\n    raise exception 'no such plan: %', p_plan using errcode = '22023';\n  end if;\n\n  select coalesce(p_status, s.status) into next_status\n    from public.subscriptions s where s.organisation_id = p_organisation;\n\n  update public.subscriptions s\n     set plan                 = p_plan,\n         status               = coalesce(p_status, s.status),\n         -- Seats can be negotiated above the catalogue, and a plan change\n         -- never silently takes them away. Reducing someone's seat count is a\n         -- decision for a person, not a side effect of applying a tier.\n         seats                = greatest(catalogue.seats, s.seats),\n         data_source_limit    = catalogue.data_source_limit,\n         ai_credits_monthly   = catalogue.ai_credits_monthly,\n         price_cents_monthly  = coalesce(catalogue.price_cents_monthly, s.price_cents_monthly),\n         currency_code        = catalogue.currency_code,\n         current_period_start = coalesce(p_period_start, s.current_period_start),\n         current_period_end   = coalesce(p_period_end, s.current_period_end),\n         -- Becoming active ends the arrears and the trial in one step.\n         grace_until          = case when next_status = 'active' then null else s.grace_until end,\n         trial_ends_at        = case when next_status = 'active' then null else s.trial_ends_at end,\n         cancelled_at         = case when next_status = 'cancelled'\n                                     then coalesce(s.cancelled_at, now()) else null end,\n         activated_at         = case when next_status = 'active'\n                                     then now() else s.activated_at end\n   where s.organisation_id = p_organisation\n  returning * into updated;\n\n  if not found then\n    raise exception 'organisation % has no subscription', p_organisation\n      using errcode = 'P0002';\n  end if;\n\n  insert into public.audit_logs\n    (organisation_id, actor_id, action, entity_type, entity_id, summary, metadata)\n  values\n    (p_organisation, auth.uid(), 'subscription.plan_applied', 'subscription', updated.id::text,\n     catalogue.name,\n     jsonb_build_object('plan', p_plan, 'status', updated.status));\n\n  return updated;\nend $$;\n\nrevoke all on function public.apply_subscription_plan(uuid, public.subscription_plan, public.subscription_status, timestamptz, timestamptz) from public, anon, authenticated;\n\n-- ── step 1: the customer asks ─────────────────────────────────────────────\n--\n-- Returns the reference to quote on the transfer. Deliberately says nothing\n-- about the subscription itself: asking does not change what the organisation\n-- currently has, and a request left unpaid must not remove anything either.\ncreate or replace function public.request_subscription(\n  p_plan        public.subscription_plan,\n  p_term_months integer default 1\n)\nreturns public.subscription_activations\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  catalogue public.subscription_plans;\n  org       uuid;\n  amount    integer;\n  created   public.subscription_activations;\nbegin\n  if auth.uid() is null then\n    raise exception 'not signed in' using errcode = '28000';\n  end if;\n  if p_term_months not in (1, 12) then\n    raise exception 'a subscription is bought by the month or by the year'\n      using errcode = '22023';\n  end if;\n\n  -- The organisation is taken from the caller's own membership rather than\n  -- from an argument, so nobody can open a request against a company they\n  -- happen to know the identifier of.\n  select m.organisation_id into org\n    from public.organisation_members m\n   where m.user_id = auth.uid()\n     and m.status = 'active'\n     and amryn.has_permission(m.organisation_id, 'manage_billing')\n   order by m.joined_at\n   limit 1;\n\n  if org is null then\n    raise exception 'only someone who manages billing can request a subscription'\n      using errcode = '42501';\n  end if;\n\n  select * into catalogue from public.subscription_plans where plan = p_plan;\n  if not found then\n    raise exception 'no such plan: %', p_plan using errcode = '22023';\n  end if;\n  if catalogue.contact_sales then\n    raise exception 'the % plan is arranged with us directly', catalogue.name\n      using errcode = '22023',\n            hint = 'Email the team and we will put the agreement together.';\n  end if;\n\n  amount := case when p_term_months = 12\n                 then coalesce(catalogue.price_cents_annual, catalogue.price_cents_monthly * 12)\n                 else catalogue.price_cents_monthly end;\n  if amount is null then\n    raise exception 'the % plan has no published price', catalogue.name\n      using errcode = '22023';\n  end if;\n\n  -- Supersede whatever was open. Someone who changes their mind before paying\n  -- should not have to ask an operator to clear the old request first.\n  update public.subscription_activations\n     set state = 'cancelled'\n   where organisation_id = org\n     and state in ('awaiting_payment', 'payment_confirmed');\n\n  insert into public.subscription_activations\n    (organisation_id, plan, term_months, amount_cents, currency_code, reference, requested_by)\n  values\n    (org, p_plan, p_term_months, amount, catalogue.currency_code,\n     -- Short enough to be typed into a banking app's reference field, which is\n     -- commonly twenty characters, and long enough not to collide.\n     'AMR-' || upper(encode(gen_random_bytes(4), 'hex')),\n     auth.uid())\n  returning * into created;\n\n  insert into public.audit_logs\n    (organisation_id, actor_id, action, entity_type, entity_id, summary, metadata)\n  values\n    (org, auth.uid(), 'subscription.requested', 'subscription_activation', created.id::text,\n     catalogue.name,\n     jsonb_build_object('plan', p_plan, 'term_months', p_term_months, 'reference', created.reference));\n\n  return created;\nend $$;\n\n-- ── step 3: an operator confirms the money arrived ────────────────────────\n--\n-- Takes the hash, not the token. The link is generated by the application,\n-- shown once to the operator who will send it, and never stored anywhere it\n-- could be read back — the same treatment an invitation gets.\n--\n-- Revoked from every signed-in role. Confirming a payment is an operator\n-- action carried out with the service role; a customer with manage_billing\n-- must not be able to confirm their own transfer.\ncreate or replace function public.issue_activation(\n  p_activation uuid,\n  p_token_hash text,\n  p_confirmed_by uuid default null,\n  p_note       text default null,\n  p_valid_for  interval default interval '14 days'\n)\nreturns public.subscription_activations\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  updated public.subscription_activations;\nbegin\n  update public.subscription_activations a\n     set state        = 'payment_confirmed',\n         token_hash   = p_token_hash,\n         confirmed_by = p_confirmed_by,\n         confirmed_at = now(),\n         payment_note = p_note,\n         expires_at   = now() + p_valid_for\n   where a.id = p_activation\n     and a.state = 'awaiting_payment'\n  returning * into updated;\n\n  if not found then\n    raise exception 'no activation awaiting payment with id %', p_activation\n      using errcode = 'P0002';\n  end if;\n\n  insert into public.audit_logs\n    (organisation_id, actor_id, action, entity_type, entity_id, summary, metadata)\n  values\n    (updated.organisation_id, p_confirmed_by, 'subscription.payment_confirmed',\n     'subscription_activation', updated.id::text, updated.reference,\n     jsonb_build_object('plan', updated.plan, 'amount_cents', updated.amount_cents));\n\n  return updated;\nend $$;\n\nrevoke all on function public.issue_activation(uuid, text, uuid, text, interval) from public, anon, authenticated;\n\n-- ── what the activation page may say before anyone is signed in ───────────\n--\n-- Possession of the link is the whole authorisation, so this returns only what\n-- the page needs to render: which organisation, which plan, and whether the\n-- link is still good. Not the amount, not the reference, not who paid.\ncreate or replace function public.activation_preview(p_token text)\nreturns table (\n  organisation_name text,\n  plan              public.subscription_plan,\n  plan_name         text,\n  term_months       integer,\n  state             text\n)\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  hashed text := encode(digest(coalesce(p_token, ''), 'sha256'), 'hex');\n  record_ record;\nbegin\n  select a.*, o.name as org_name, p.name as tier_name\n    into record_\n    from public.subscription_activations a\n    join public.organisations o on o.id = a.organisation_id\n    join public.subscription_plans p on p.plan = a.plan\n   where a.token_hash = hashed;\n\n  if record_.id is null then\n    return query select null::text, null::public.subscription_plan, null::text, null::integer, 'unknown'::text;\n    return;\n  end if;\n\n  return query select\n    record_.org_name::text,\n    record_.plan,\n    record_.tier_name::text,\n    record_.term_months,\n    case\n      when record_.state = 'activated' then 'already_used'\n      when record_.state <> 'payment_confirmed' then 'unavailable'\n      when record_.expires_at is not null and record_.expires_at < now() then 'expired'\n      else 'ready'\n    end::text;\nend $$;\n\n-- ── step 4: the customer redeems the link ─────────────────────────────────\n--\n-- The period runs from redemption rather than from confirmation, so a link\n-- sent on a Friday and opened on a Monday does not cost the customer a\n-- weekend. The activation is marked used in the same transaction that makes\n-- the subscription active, so a link cannot be redeemed twice.\ncreate or replace function public.redeem_activation(p_token text)\nreturns public.subscriptions\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  hashed  text := encode(digest(coalesce(p_token, ''), 'sha256'), 'hex');\n  claim   public.subscription_activations;\n  result  public.subscriptions;\nbegin\n  -- for update, so two clicks on the same link race for the row rather than\n  -- both reading it as unused.\n  select * into claim\n    from public.subscription_activations\n   where token_hash = hashed\n   for update;\n\n  if claim.id is null then\n    raise exception 'this activation link is not recognised' using errcode = '22023';\n  end if;\n  if claim.state = 'activated' then\n    raise exception 'this activation link has already been used' using errcode = '22023';\n  end if;\n  if claim.state <> 'payment_confirmed' then\n    raise exception 'this activation link is not ready to be used' using errcode = '22023';\n  end if;\n  if claim.expires_at is not null and claim.expires_at < now() then\n    update public.subscription_activations set state = 'expired' where id = claim.id;\n    raise exception 'this activation link has expired' using errcode = '22023',\n      hint = 'Ask us for a new one; the payment is still on record.';\n  end if;\n\n  result := public.apply_subscription_plan(\n    claim.organisation_id,\n    claim.plan,\n    'active',\n    now(),\n    now() + make_interval(months => claim.term_months));\n\n  update public.subscriptions\n     set last_payment_at = now(),\n         activated_by    = auth.uid()\n   where organisation_id = claim.organisation_id\n  returning * into result;\n\n  update public.subscription_activations\n     set state = 'activated', activated_at = now(), activated_by = auth.uid()\n   where id = claim.id;\n\n  insert into public.audit_logs\n    (organisation_id, actor_id, action, entity_type, entity_id, summary, metadata)\n  values\n    (claim.organisation_id, auth.uid(), 'subscription.activated',\n     'subscription_activation', claim.id::text, claim.reference,\n     jsonb_build_object('plan', claim.plan, 'term_months', claim.term_months));\n\n  return result;\nend $$;\n\n-- ── who may see an activation record ──────────────────────────────────────\nalter table public.subscription_activations enable row level security;\n\n-- Readable by whoever manages billing, so the customer can see the reference\n-- to pay against and what has been confirmed.\ncreate policy subscription_activations_read on public.subscription_activations\n  for select to authenticated\n  using (amryn.has_permission(organisation_id, 'manage_billing'));\n\n-- No write policy, and the grant is revoked as well. Every write goes through\n-- one of the definer functions above, which is what keeps the confirmation\n-- step out of the customer's hands: a policy alone would let anyone with\n-- manage_billing set state = 'activated' on their own row, because Row Level\n-- Security decides rows, not columns.\n--\n-- Deliberately not forced: the definer functions run as this table's owner,\n-- and forcing it would refuse them along with everyone else. The revoked grant\n-- is the stronger control here and is unaffected either way — the same\n-- reasoning, and the same exception, as audit_logs and mfa_recovery_codes.\nrevoke insert, update, delete on public.subscription_activations from authenticated;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- 8. Who may read the catalogue\n-- ═══════════════════════════════════════════════════════════════════════════\n\nalter table public.subscription_plans  enable row level security;\nalter table public.subscription_plans  force row level security;\nalter table public.entitlements        enable row level security;\nalter table public.entitlements        force row level security;\nalter table public.plan_entitlements   enable row level security;\nalter table public.plan_entitlements   force row level security;\n\n-- The catalogue is the price list. It is on the marketing site, so treating it\n-- as a secret from a signed-in customer would be theatre.\n--\n-- `to public` rather than `to authenticated` because forcing row level\n-- security applies to the table's owner too, and the definer functions above\n-- read these rows as the owner. A policy naming only `authenticated` would\n-- leave apply_subscription_plan() reading an empty catalogue and reporting\n-- \"no such plan\" for a tier that is sitting right there. The grant, not the\n-- policy, is what keeps anonymous callers out: migration 09 grants these\n-- tables to `authenticated` alone, and `anon` holds nothing.\ncreate policy subscription_plans_read on public.subscription_plans\n  for select to public using (true);\n\ncreate policy entitlements_read on public.entitlements\n  for select to public using (true);\n\ncreate policy plan_entitlements_read on public.plan_entitlements\n  for select to public using (true);\n\n-- Nobody signed in changes the price list. It changes by migration, or by an\n-- operator holding the service role.\nrevoke insert, update, delete on public.subscription_plans from authenticated;\nrevoke insert, update, delete on public.entitlements from authenticated;\nrevoke insert, update, delete on public.plan_entitlements from authenticated;\n\ngrant select on public.organisation_entitlements to authenticated;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- 9. Privileges for the role that does the operator's work\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- Found while writing the confirmation step, and older than this migration.\n--\n-- Migration 09 established default privileges so that a table added by a later\n-- migration is reachable by `authenticated` — the snapshot problem, fixed for\n-- one role. `service_role` has exactly the same problem and was not covered:\n-- Supabase grants it the public schema once, at project creation, and that\n-- grant likewise says nothing about tables that do not exist yet. Every table\n-- added since migration 09 — rate limits, data requests, and now these — was\n-- therefore invisible to the one client that is supposed to be able to reach\n-- everything, and would have failed the first time an operator tool touched\n-- one, reported as a missing table rather than as a missing privilege.\n--\n-- Row Level Security is not weakened by any of this: service_role bypasses it\n-- by design, which is why the key never reaches a browser.\ngrant all on all tables in schema public to service_role;\ngrant all on all sequences in schema public to service_role;\n\nalter default privileges in schema public\n  grant all on tables to service_role;\n\nalter default privileges in schema public\n  grant all on sequences to service_role;\n\n-- The two functions the operator holds alone. Revoked from every signed-in\n-- role above; granted here to the one role that is meant to have them, because\n-- `revoke ... from public` took the default away from service_role as well.\ngrant execute on function public.apply_subscription_plan(uuid, public.subscription_plan, public.subscription_status, timestamptz, timestamptz) to service_role;\ngrant execute on function public.issue_activation(uuid, text, uuid, text, interval) to service_role;\n\nnotify pgrst, 'reload schema';\n\n-- ══════════════════════════════════════════════════════════════════════\n-- 20260901120000_17_onboarding.sql\n-- ══════════════════════════════════════════════════════════════════════\ndo $setup$ begin raise notice 'applying 20260901120000_17_onboarding.sql'; end $setup$;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- Amryn™ AIGrowthIntelligence® Software\n-- Migration 17 — Intelligence onboarding\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- Creating an organisation takes four fields and thirty seconds. What the\n-- platform needs in order to say anything useful about a business takes rather\n-- more: its shape, what it is trying to achieve, which systems hold its\n-- numbers, and who it competes with. Until now none of that was ever asked,\n-- so a new customer arrived at a Command Centre with nothing in it and no path\n-- from there to something worth looking at.\n--\n-- Seven steps ask for it. This migration is what makes them resumable.\n--\n-- ── why a record and not a wizard ─────────────────────────────────────────\n-- The obvious implementation keeps the answers in the browser until the last\n-- step and writes everything at the end. That fails the way real onboarding\n-- actually goes: it is done over several sittings, by more than one person,\n-- and half of it is delegated (\"ask the accountant which system that is\").\n-- Anything held client-side is lost by then.\n--\n-- So each step writes as it is answered, to the real tables — a branch entered\n-- in step two is a branch, not a draft — and this record tracks only which\n-- steps have been answered, which were skipped, and where to resume.\n\ncreate table public.onboarding_progress (\n  organisation_id uuid primary key references public.organisations (id) on delete cascade,\n\n  -- Where \"continue\" goes.\n  current_step    text not null default 'identity',\n  completed_steps text[] not null default '{}',\n  -- Skipping is a first-class answer, not an absence of one. A business with\n  -- one site should not be made to invent a structure, and the review step has\n  -- to be able to tell \"not applicable\" from \"not yet done\".\n  skipped_steps   text[] not null default '{}',\n\n  -- What was said that has no table of its own — how the business describes\n  -- itself, roughly how large it is, which of its systems are on paper. Kept\n  -- as a document because the questions will change and a column per question\n  -- would mean a migration each time somebody rewords one.\n  answers         jsonb not null default '{}'::jsonb,\n\n  started_at      timestamptz not null default now(),\n  completed_at    timestamptz,\n  -- When the twin was first built from the answers. Separate from completion:\n  -- somebody can finish the questions and not press the button.\n  initialised_at  timestamptz,\n\n  created_at      timestamptz not null default now(),\n  updated_at      timestamptz not null default now(),\n\n  -- A misspelled step would otherwise sit in the array for ever, never\n  -- matching, and the customer would be asked the same question at every\n  -- sitting with no error anywhere to explain it.\n  constraint steps_are_known check (\n    current_step = any (array['identity','structure','objectives','systems','data','market','review'])\n    and completed_steps <@ array['identity','structure','objectives','systems','data','market','review']\n    and skipped_steps   <@ array['identity','structure','objectives','systems','data','market','review']\n  ),\n  -- A step cannot be both answered and skipped. Without this the review page\n  -- has two contradictory sources for the same question.\n  constraint not_both_done_and_skipped check (\n    not (completed_steps && skipped_steps)\n  )\n);\n\ncomment on table public.onboarding_progress is\n  'Which of the seven onboarding steps an organisation has answered, skipped, and where to resume. The answers themselves go to the real tables; only what has no table of its own is kept here.';\n\ncreate trigger onboarding_progress_touch\n  before update on public.onboarding_progress\n  for each row execute function amryn.touch_updated_at();\n\nalter table public.onboarding_progress enable row level security;\nalter table public.onboarding_progress force row level security;\n\n-- Every member can see how far setup has got — a colleague who lands on a half\n-- empty Command Centre deserves to know why rather than assume it is broken.\ncreate policy onboarding_progress_read on public.onboarding_progress\n  for select to authenticated\n  using (amryn.is_member(organisation_id));\n\ncreate policy onboarding_progress_write on public.onboarding_progress\n  for all to authenticated\n  using (amryn.has_permission(organisation_id, 'manage_organisation'))\n  with check (amryn.has_permission(organisation_id, 'manage_organisation'));\n\n-- ── the guard from migration 16 does not reach this table ─────────────────\n--\n-- refuse_lapsed_write() was attached by iterating the catalogue at the moment\n-- migration 16 ran. That is a snapshot, and this table did not exist yet — so\n-- it carries no trigger, and neither will anything added after it unless\n-- somebody remembers.\n--\n-- Here that is the right answer and is stated rather than inherited: setting\n-- up is how a trial becomes a customer, and an organisation whose trial ran\n-- out mid-onboarding must be able to finish and then pay. Test 19 asserts that\n-- every other table with an organisation_id either carries the guard or is on\n-- the exemption list, so the next table added is a failing test rather than a\n-- silent gap.\n\n-- ── opening the record ────────────────────────────────────────────────────\n--\n-- Definer, because the first caller is the person who has just created the\n-- organisation and the row has to exist before anything can be saved against\n-- it. Idempotent, so a refresh or a second tab costs nothing.\ncreate or replace function public.ensure_onboarding(p_organisation uuid)\nreturns public.onboarding_progress\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  result public.onboarding_progress;\nbegin\n  if not amryn.is_member(p_organisation) then\n    raise exception 'not a member of that organisation' using errcode = '42501';\n  end if;\n\n  insert into public.onboarding_progress (organisation_id)\n  values (p_organisation)\n  on conflict (organisation_id) do nothing;\n\n  select * into result from public.onboarding_progress\n   where organisation_id = p_organisation;\n\n  return result;\nend $$;\n\n-- ── finishing ─────────────────────────────────────────────────────────────\n--\n-- One statement, so that \"the questions are answered\" and \"the twin has been\n-- built\" cannot disagree, and so the audit entry is written in the same\n-- transaction as the thing it records.\ncreate or replace function public.complete_onboarding(p_organisation uuid)\nreturns public.onboarding_progress\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  result public.onboarding_progress;\nbegin\n  if not amryn.has_permission(p_organisation, 'manage_organisation') then\n    raise exception 'only an administrator can finish setting up' using errcode = '42501';\n  end if;\n\n  update public.onboarding_progress\n     set completed_at   = coalesce(completed_at, now()),\n         initialised_at = coalesce(initialised_at, now()),\n         current_step   = 'review'\n   where organisation_id = p_organisation\n  returning * into result;\n\n  if not found then\n    raise exception 'that organisation has not started setting up' using errcode = 'P0002';\n  end if;\n\n  insert into public.audit_logs\n    (organisation_id, actor_id, action, entity_type, entity_id, summary)\n  values\n    (p_organisation, auth.uid(), 'onboarding.completed', 'organisation',\n     p_organisation::text, 'Setup finished and the twin initialised');\n\n  return result;\nend $$;\n\nnotify pgrst, 'reload schema';\n\n-- ══════════════════════════════════════════════════════════════════════\n-- 20260902130000_18_stock_control.sql\n-- ══════════════════════════════════════════════════════════════════════\ndo $setup$ begin raise notice 'applying 20260902130000_18_stock_control.sql'; end $setup$;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- Amryn™ AIGrowthIntelligence® Software\n-- Migration 18 — Advanced Inventory Control\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- The inventory module was built against the second Excel workbook and read a\n-- fixed dataset. Every screen worked, every calculation was right, and none of\n-- it was anybody's stock: a real organisation opening Advanced Inventory\n-- Control was shown a demonstration pharmacy's shelves. The module was\n-- recently changed to say \"not connected\" instead, which was honest and not a\n-- product. This is the table behind it.\n--\n-- ── the shape follows the workbook, because the workbook is the product ───\n-- SETTINGS holds who is auditing what, on which shift; AUDIT LOG holds one row\n-- per stock line. That is a session and its lines, so it is two tables rather\n-- than one — and the second table is what makes a history possible. An audit\n-- in March and an audit in June are two rows in `stock_audits`, and \"what did\n-- the shelves look like at year end\" becomes answerable instead of being\n-- overwritten.\n--\n-- ── what is deliberately not here ─────────────────────────────────────────\n-- Compliance profiles stay in code. They encode what a sector's regulator\n-- requires — SAHPRA retention, disposal evidence, who signs an audit off —\n-- and a change to one should arrive as a reviewed diff, not as somebody\n-- editing a text field on a Tuesday. `complianceProfile()` already falls back\n-- to the general profile for an id it does not know, so adding a fourth is a\n-- code change with no migration.\n\n-- ── the vocabulary ────────────────────────────────────────────────────────\n--\n-- Snake case, not the workbook's display strings. The six actions are labels\n-- an operator reads — \"Marked Down / Clearance\" — and rewording a label should\n-- not be a schema change. The display strings live in the engine, where they\n-- belong, and the mapping is one table in src/lib/inventory/mapping.ts.\ncreate type public.stock_action as enum (\n  'pending_review',\n  'left_on_shelf',\n  'removed_from_shelf',\n  'returned_to_supplier',\n  'marked_down',\n  'destroyed'\n);\n\ncreate type public.stock_audit_status as enum ('draft', 'in_progress', 'complete');\n\n-- ── the session ───────────────────────────────────────────────────────────\n\ncreate table public.stock_audits (\n  id                    uuid primary key default gen_random_uuid(),\n  organisation_id       uuid not null references public.organisations (id) on delete cascade,\n  -- Which site was walked. Null for an organisation that does not separate\n  -- them, which is the single-shop case and must stay easy.\n  branch_id             uuid references public.branches (id) on delete set null,\n\n  -- SETTINGS!B4–B7. Kept as text rather than as references to people: the\n  -- person who walked the shelves is often not a platform user, and an audit\n  -- that cannot record a stocktaker because they have no login is an audit\n  -- nobody does.\n  site_name             text not null,\n  auditor_name          text not null default '',\n  responsible_name      text not null default '',\n  shift                 text not null default '',\n\n  -- Resolved in code against COMPLIANCE_PROFILES; an unknown id falls back to\n  -- the general profile rather than failing, so a profile removed from the\n  -- code does not strand an audit.\n  compliance_profile_id text not null default 'general-inventory',\n\n  audit_date            date not null default current_date,\n  status                public.stock_audit_status not null default 'draft',\n\n  created_by            uuid references auth.users (id) on delete set null,\n  completed_at          timestamptz,\n  created_at            timestamptz not null default now(),\n  updated_at            timestamptz not null default now(),\n\n  -- A completed audit is one with a completion time, and an incomplete one is\n  -- not. Without this the report can be generated from a session somebody is\n  -- still halfway through, and dated as though it were finished.\n  constraint complete_carries_a_time check (\n    (status = 'complete') = (completed_at is not null)\n  )\n);\n\ncomment on table public.stock_audits is\n  'One stocktake: who walked which site, on what date, against which sector profile. The lines are in stock_items.';\n\ncreate index stock_audits_org_idx on public.stock_audits (organisation_id, audit_date desc);\n\ncreate trigger stock_audits_touch\n  before update on public.stock_audits\n  for each row execute function amryn.touch_updated_at();\n\n-- ── the lines ─────────────────────────────────────────────────────────────\n\ncreate table public.stock_items (\n  id              uuid primary key default gen_random_uuid(),\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  audit_id        uuid not null references public.stock_audits (id) on delete cascade,\n\n  -- AUDIT LOG!B–H.\n  product_name    text not null,\n  sku             text not null default '',\n  batch_number    text not null default '',\n  department      text not null default '',\n  location        text not null default '',\n  qty             integer not null default 0 check (qty >= 0),\n  expiry_date     date not null,\n\n  -- AUDIT LOG!I–N. `action` is nullable-by-default rather than null: a line\n  -- nobody has looked at is 'pending_review', which is a state the workbook\n  -- names, and the dormancy rules test against it. Null would make every rule\n  -- carry a coalesce.\n  action          public.stock_action not null default 'pending_review',\n  actioned_by     text not null default '',\n  actioned_on     date,\n  notes           text not null default '',\n\n  -- AUDIT LOG!O — the auditor's tick that this line has been dealt with.\n  verified        boolean not null default false,\n\n  -- Cents, like every other money column here, so the report can state\n  -- capital at risk without a float. Null where the cost is not known, which\n  -- is common and must not read as zero.\n  unit_cost_cents bigint check (unit_cost_cents is null or unit_cost_cents >= 0),\n\n  -- Set where a sales feed shows the item moving. Overrides the workbook's\n  -- inference that an item left on the shelf and not near expiry is dormant —\n  -- an inference it makes because it cannot see turnover.\n  has_movement    boolean,\n\n  -- The order the lines were counted in. The report prints them as numbered\n  -- rows and an auditor reads down the shelf, so the order is information.\n  position        integer not null default 0,\n\n  created_at      timestamptz not null default now(),\n  updated_at      timestamptz not null default now(),\n\n  -- An action that has been taken has a date. Recording one without the other\n  -- is how a disposal ends up undocumented, which is the specific thing the\n  -- insurance and regulator notes on the report depend on.\n  constraint actioned_lines_carry_a_date check (\n    action = 'pending_review' or actioned_on is not null\n  )\n);\n\ncomment on table public.stock_items is\n  'One line of a stocktake. Expiry status, dormancy and value at risk are computed by the engine from these columns rather than stored, so a figure can never disagree with its own formula.';\n\ncreate index stock_items_audit_idx on public.stock_items (audit_id, position);\ncreate index stock_items_org_idx on public.stock_items (organisation_id);\n-- Expiry is what every report section sorts and filters on.\ncreate index stock_items_expiry_idx on public.stock_items (organisation_id, expiry_date);\n\ncreate trigger stock_items_touch\n  before update on public.stock_items\n  for each row execute function amryn.touch_updated_at();\n\n-- ── the permission ────────────────────────────────────────────────────────\n--\n-- A new key rather than reusing import_data. Importing a spreadsheet and\n-- marking a batch destroyed are different acts with different consequences,\n-- and the second is the one a regulator asks about. Naming it separately means\n-- it can be granted separately.\ninsert into public.permissions (key, category, description) values\n  ('manage_inventory', 'Operations', 'Record stocktakes, action stock lines and import stock');\n\ndo $$\ndeclare\n  r public.org_role;\nbegin\n  -- Everyone who can already see operational data, plus the analyst who does\n  -- the importing. Deliberately not the viewer: actioning a line is a\n  -- decision about stock, not a way of reading about it.\n  foreach r in array array[\n    'super_admin','org_admin','executive','regional_manager',\n    'branch_manager','department_manager','analyst'\n  ]::public.org_role[]\n  loop\n    insert into public.role_permissions (role, permission_key)\n    values (r, 'manage_inventory')\n    on conflict do nothing;\n  end loop;\nend $$;\n\n-- ── who may read and write them ───────────────────────────────────────────\n\nalter table public.stock_audits enable row level security;\nalter table public.stock_audits force row level security;\nalter table public.stock_items  enable row level security;\nalter table public.stock_items  force row level security;\n\ncreate policy stock_audits_read on public.stock_audits\n  for select to authenticated\n  using (amryn.has_permission(organisation_id, 'view_operations_data'));\n\ncreate policy stock_audits_write on public.stock_audits\n  for all to authenticated\n  using (amryn.has_permission(organisation_id, 'manage_inventory'))\n  with check (amryn.has_permission(organisation_id, 'manage_inventory'));\n\ncreate policy stock_items_read on public.stock_items\n  for select to authenticated\n  using (amryn.has_permission(organisation_id, 'view_operations_data'));\n\ncreate policy stock_items_write on public.stock_items\n  for all to authenticated\n  using (amryn.has_permission(organisation_id, 'manage_inventory'))\n  with check (amryn.has_permission(organisation_id, 'manage_inventory'));\n\n-- ── the lapsed-subscription guard ─────────────────────────────────────────\n--\n-- Attached by hand, and that is the point. Migration 16 attached it by\n-- iterating the catalogue at the moment it ran, which is a snapshot: a table\n-- added afterwards carries no trigger and nothing about writing this migration\n-- would say so. Test 19 asserts the whole list, so leaving these two out is a\n-- failing test rather than a silent gap — which is exactly what it was written\n-- to catch.\n--\n-- Stock is business data, so it is guarded rather than exempt: an organisation\n-- whose subscription has lapsed keeps reading its stocktakes and its report,\n-- and cannot record new ones.\ncreate trigger zz_subscription_stock_audits\n  before insert or update or delete on public.stock_audits\n  for each row execute function amryn.refuse_lapsed_write();\n\ncreate trigger zz_subscription_stock_items\n  before insert or update or delete on public.stock_items\n  for each row execute function amryn.refuse_lapsed_write();\n\nnotify pgrst, 'reload schema';\n\n-- ══════════════════════════════════════════════════════════════════════\n-- Did it work?\n-- ══════════════════════════════════════════════════════════════════════\ndo $setup$\ndeclare\n  tables_found bigint;\n  perms_found  bigint;\n  grants_found bigint;\nbegin\n  select count(*) into tables_found from pg_tables where schemaname = 'public';\n  select count(*) into perms_found  from public.permissions;\n  select count(*) into grants_found from public.role_permissions;\n\n  if tables_found <> 49 then\n    raise exception 'expected 49 tables, found %', tables_found;\n  end if;\n  if perms_found <> 30 then\n    raise exception 'expected 30 permissions, found %', perms_found;\n  end if;\n  if grants_found < 100 then\n    raise exception 'expected the role matrix to be seeded, found % grants', grants_found;\n  end if;\n\n  raise notice 'setup complete: % tables, % permissions, % role grants',\n    tables_found, perms_found, grants_found;\nend $setup$;\n\ncommit;\n\n-- Outside the transaction: PostgREST answers from a cached copy of the\n-- schema, and nothing above is visible to the application until it is told.\nnotify pgrst, 'reload schema';\n";

